#!/usr/bin/env node
/**
 * suite-checks.js —— 【第 64 轮·删除合并】代码与文案静态检查（i18n 键、音效 DSP、按钮不透明度/歌曲高亮透明度/圆角覆盖率、JSX 导入守卫）
 * 成员 6 个：check-i18n-keys.js、check-sound-effect-dsp.js、check-button-opacity-coverage.js、check-song-highlight-opacity.js、check-button-radius-coverage.js、sim-jsx-import-guard.js
 *
 * 本文件由「成员源码原样嵌入」生成：每个成员在套件里仍然是**它自己那份源码**，
 * 跑在独立的作用域里（自己的 require / process / console / __dirname / __filename /
 * module / exports），彼此不共享变量；成员的 `process.exit(c)` 由套件记录退出码
 *（不真的退出 —— 与 run.py 的 runner 同一种 shim，行为逐字等价）。
 *
 * 为什么合并：scripts/ 里躺着上百个两三千字节的独立脚本，用户第 64 轮明确要求
 * 「删除合并 scripts 文件夹中的脚本文件」；套件把同主题的契约收进一个文件，
 * 覆盖率一个成员都不少（合并前逐文件 __EXIT__ 与合并后逐成员 exit 已逐项比对）。
 *
 * 注意：scripts/ 不参与打包（不进 App bundle），所以这一步**不省电、不降温** ——
 * 省电的改动都在 src/ 与 ios/ 里（见改动清单第六十四轮）。
 *
 * 运行：python "C:\Users\Q\AppData\Local\Temp\lx-jsrun\run.py" scripts/suite-checks.js --brief
 *   `--brief` 只看 FAIL / ===== / 结果 行；去掉 `--brief` 看每个成员的全部输出。
 * 也可以用真实 node 跑（`node scripts/suite-checks.js`、`npm run lint:sound-effect-dsp`）：
 * 成员一律用 path.resolve(__dirname, '..') 定位工程根，套件把**自己的** __dirname
 * 传下去，所以两种环境下指向同一棵树。
 * 退出码：全部成员 exit 0 时为 0，否则为第一个非 0 的成员退出码。
 */
'use strict'

const THEME = "代码与文案静态检查（i18n 键、音效 DSP、按钮不透明度/歌曲高亮透明度/圆角覆盖率、JSX 导入守卫）"

const MEMBERS = [
  { n: "check-i18n-keys.js", s: "/**\n * check-i18n-keys.js\n *\n * 文案 key 存在性检查：源码里引用的翻译 key 必须都能在 zh-cn.json 里找到。\n *\n * 为什么需要它：`src/lang/i18n.ts` 的 `getMessage` 对缺失 key 返回 `''`\n * （`msg[key] ?? fallback[key] ?? ''`）—— 不抛错、不打 warning、不做兜底文案。\n * 结果是 UI 上直接**空白**，而 tsc / eslint 全绿（`t` 的签名是 `(key: string) => string`，\n * key 不在类型体系里）。真实事故：音效弹层的两个环境混响项\n * `setting_play_sound_effect_env_matrix_1` / `_matrix_2` 只有 labelKey、没有词条，\n * 环境混响列表里就多了两个「只有勾选框、没有文字」的项\n * （播放详情 → 音效，2026-09-30 修复）。\n *\n * 只检查**字面量 key**（`t('xxx')`、`labelKey: 'xxx'` 等）；模板字符串 / 变量拼接的\n * 动态 key 静态不可判定，直接跳过（宁可漏报，不可误报）。\n *\n * 运行：node scripts/check-i18n-keys.js\n * 退出码：有缺失 key 时为 1。\n */\n\nconst fs = require('fs')\nconst path = require('path')\n\nconst ROOT = path.join(__dirname, '..')\nconst MESSAGES = 'src/lang/zh-cn.json'\nconst SRC = 'src'\n\n/** 匹配源码中的字面量 key */\nconst KEY_PATTERNS = [\n  { re: /\\bt\\(\\s*'([^'\\\\]*)'/g, kind: 't()' },\n  { re: /\\bt\\(\\s*\"([^\"\\\\]*)\"/g, kind: 't()' },\n  { re: /\\b[A-Za-z_$][\\w$]*[Kk]ey\\s*:\\s*'([^'\\\\]*)'/g, kind: 'xxxKey' },\n  { re: /\\b[A-Za-z_$][\\w$]*[Kk]ey\\s*:\\s*\"([^\"\\\\]*)\"/g, kind: 'xxxKey' },\n]\n\n/** key 的合法形态：小写字母开头，只含小写字母/数字/下划线。\n *  以下一律跳过 —— 避免把非文案 key 或动态 key 误报成缺失：\n *    - 模板串（含 `${}`）、大写开头、含中文/空格；\n *    - **含点的设置项路径**（如 `SliderRow` 的 `settingKey: 'theme.blur'` 会被\n *      `xxxKey:` 规则撞上）。实测 zh-cn.json 全部 769 个词条中没有任何含点的 key，\n *      故按形状排除是安全的。 */\nconst KEY_SHAPE = /^[a-z][a-z0-9_]*$/\n\nfunction collectFiles(dir, out = []) {\n  for (const name of fs.readdirSync(dir)) {\n    const p = path.join(dir, name)\n    const st = fs.statSync(p)\n    if (st.isDirectory()) {\n      if (name !== 'node_modules') collectFiles(p, out)\n    } else if (/\\.tsx?$/.test(name)) out.push(p)\n  }\n  return out\n}\n\nconst FILES = collectFiles(path.join(ROOT, SRC)).map((p) => [\n  path.relative(ROOT, p).replace(/\\\\/g, '/'),\n  fs.readFileSync(p, 'utf8'),\n])\n\n/**\n * 收集字面量 key 引用。\n * @returns {Map<string, string[]>} key → ['相对路径:行号 (来源形态)']\n */\nfunction collectRefs(files = FILES) {\n  const refs = new Map()\n  for (const [rel, text] of files) {\n    const lines = text.split('\\n')\n    for (const { re, kind } of KEY_PATTERNS) {\n      re.lastIndex = 0\n      let m\n      while ((m = re.exec(text))) {\n        const key = m[1]\n        if (!KEY_SHAPE.test(key)) continue\n        const line = text.slice(0, m.index).split('\\n').length\n        const list = refs.get(key) ?? []\n        list.push(`${rel}:${line} (${kind})`)\n        refs.set(key, list)\n      }\n    }\n    void lines\n  }\n  return refs\n}\n\n/** @returns {Map<string, string[]>} 缺失的 key → 引用点 */\nfunction findMissing(messages, refs = collectRefs()) {\n  const missing = new Map()\n  for (const [key, sites] of refs) {\n    if (messages[key] == null) missing.set(key, sites)\n  }\n  return missing\n}\n\n// ---------------------------------------------------------------------------\n\nconst messages = JSON.parse(fs.readFileSync(path.join(ROOT, MESSAGES), 'utf8'))\nconst refs = collectRefs()\nconst missing = findMissing(messages, refs)\n\nconsole.log('文案 key 存在性检查\\n')\n\nlet failed = 0\nconst report = (pass, name, detail) => {\n  console.log(`${pass ? 'PASS' : 'FAIL'}  ${name}`)\n  if (detail) console.log(`      ${detail}`)\n  if (!pass) failed++\n}\n\nreport(\n  missing.size === 0,\n  `不变量1 源码引用的字面量 key 全部存在于 ${MESSAGES}`,\n  missing.size === 0\n    ? `${refs.size} 个不同 key / ${[...refs.values()].reduce((n, v) => n + v.length, 0)} 处引用，0 处缺失`\n    : [...missing.entries()]\n        .map(([key, sites]) => `\\n        缺失 [${key}] ← ${sites.join('、')}\\n          修法：在 ${MESSAGES} 补词条（缺失时 getMessage 返回空串，UI 上直接空白）`)\n        .join(''),\n)\n\n// --- 不变量 2（反例）：删掉一个**被引用**的词条后必须报出来 ---\n{\n  const victim = [...refs.keys()].find((key) => messages[key] != null)\n  if (!victim) {\n    report(false, '不变量2 反例：删词条后必须报错', '找不到任何被引用的词条，检查逻辑可能失效')\n  } else {\n    const broken = { ...messages }\n    const original = broken[victim]\n    delete broken[victim]\n    const detected = findMissing(broken, refs).has(victim)\n    // 顺带确认词条确实存在（否则「删掉了」本身无从谈起）\n    const existed = original != null\n    report(\n      detected && existed,\n      '不变量2 反例：删掉一个被引用的词条后必须报错（否则规则形同虚设）',\n      `删除 [${victim}]（原值「${original}」）后${detected ? '被报出' : '**未**被报出'}`,\n    )\n  }\n}\n\n// --- 不变量 3（反例）：形状过滤必须挡住动态 key，否则会大量误报 ---\n{\n  const legal = ['setting_ok_key', 'saved', 'understand']\n  const illegal = ['${dynamic}', 'Setting_Upper', '有中文', 'has space', 'theme.blur', '']\n  const legalPass = legal.every((s) => KEY_SHAPE.test(s))\n  const illegalPass = illegal.every((s) => !KEY_SHAPE.test(s))\n  report(\n    legalPass && illegalPass,\n    '不变量3 反例：动态 key / 非法形态必须被跳过（避免误报）',\n    `合法 ${legal.length} 个全通过、非法 ${illegal.length} 个全跳过` +\n      (legalPass && illegalPass ? '' : '（形状过滤失效，会产生误报）'),\n  )\n}\n\nconsole.log(`\\n===== ${3 - failed}/3 项通过 =====`)\n\nif (failed > 0) {\n  console.error(`\\n文案 key 检查未通过 ${failed} 项，退出码 1`)\n  process.exit(1)\n}\n" },
  { n: "check-sound-effect-dsp.js", s: "const fs = require('node:fs')\nconst path = require('node:path')\n\nconst rootPath = path.resolve(__dirname, '..')\nconst profile = JSON.parse(fs.readFileSync(path.join(rootPath, 'config/soundEffectDspProfile.json'), 'utf8'))\nconst appDelegate = fs.readFileSync(path.join(rootPath, 'ios/LxMusicMobile/AppDelegate.mm'), 'utf8')\nconst swiftPatch = fs.readFileSync(path.join(rootPath, 'patches/ios/LXEqualizerAudioMix.swift'), 'utf8')\n\nconst errors = []\n\nconst expectIncludes = (source, snippet, label) => {\n  if (!source.includes(snippet)) errors.push(`Missing ${label}: ${snippet}`)\n}\n\nconst expectCountAtLeast = (source, pattern, minCount, label) => {\n  const count = (source.match(pattern) ?? []).length\n  if (count < minCount) errors.push(`Expected at least ${minCount} matches for ${label}, found ${count}`)\n}\n\nconst expectOrdered = (source, tokens, label) => {\n  let lastIndex = -1\n  for (const token of tokens) {\n    const index = source.indexOf(token, lastIndex + 1)\n    if (index < 0) {\n      errors.push(`Missing token for ${label}: ${token}`)\n      return\n    }\n    if (index < lastIndex) {\n      errors.push(`Unexpected order for ${label}: ${token}`)\n      return\n    }\n    lastIndex = index\n  }\n}\n\nconst frequencyList = profile.equalizerFrequencies.join(', ')\nconst pitchBypass = profile.pitch.bypassThreshold\nconst eqBypass = profile.equalizerBypassThreshold\nconst q = profile.equalizerQ\nconst headroomMode = profile.equalizerHeadroomMode\nconst blockSize = profile.phaseVocoder.blockSize\nconst hopSize = profile.phaseVocoder.hopSize\nconst windowScale = profile.phaseVocoder.windowScale\nconst pitchMin = profile.pitch.minRate\nconst pitchMax = profile.pitch.maxRate\nconst pitchDefault = profile.pitch.defaultRate\nconst dynamicsMode = profile.dynamics.mode\nconst dynamicsThresholdLinear = profile.dynamics.thresholdLinear\nconst dynamicsAttack = profile.dynamics.attackSeconds\nconst dynamicsRelease = profile.dynamics.releaseSeconds\n\nexpectIncludes(appDelegate, `frequencies = @[ @${profile.equalizerFrequencies.join(', @')} ];`, 'AppDelegate equalizer frequencies')\nexpectIncludes(swiftPatch, `let lxSoundEffectBandFrequencies: [Float] = [${frequencyList}]`, 'Swift equalizer frequencies')\n\nexpectIncludes(appDelegate, `const float q = ${q}f;`, 'AppDelegate equalizer Q')\nexpectIncludes(swiftPatch, `let q: Float = ${q}`, 'Swift equalizer Q')\n\nexpectIncludes(swiftPatch, `init?(channelCount: Int, blockSize: Int = ${blockSize}, hopSize: Int = ${hopSize}) {`, 'Swift phase vocoder sizes')\nexpectCountAtLeast(appDelegate, new RegExp(`_blockSize = ${blockSize};`, 'g'), 2, 'AppDelegate phase vocoder block size')\nexpectCountAtLeast(appDelegate, new RegExp(`_hopSize = ${hopSize};`, 'g'), 2, 'AppDelegate phase vocoder hop size')\n\nexpectCountAtLeast(appDelegate, new RegExp(`${windowScale.toFixed(1)} \\\\* \\\\(1\\\\.0 - cos`, 'g'), 2, 'AppDelegate Hann window scale')\nexpectIncludes(swiftPatch, `${windowScale.toFixed(1)} * (1 - cos`, 'Swift Hann window scale')\n\nexpectCountAtLeast(appDelegate, new RegExp(`fabsf\\\\(pitchFactor - ${pitchDefault.toFixed(1)}f\\\\) < ${pitchBypass.toFixed(2)}f`, 'g'), 3, 'AppDelegate pitch bypass threshold')\nexpectIncludes(swiftPatch, `abs(pitchPlaybackRate - ${pitchDefault}) >= ${pitchBypass.toFixed(2)}`, 'Swift pitch bypass threshold')\n\nexpectCountAtLeast(appDelegate, new RegExp(`fabsf\\\\(gain\\\\) < ${eqBypass.toFixed(2)}f`, 'g'), 1, 'AppDelegate EQ bypass threshold')\nexpectIncludes(swiftPatch, `if abs(gain) < ${eqBypass.toFixed(2)} { return .bypass }`, 'Swift EQ bypass threshold')\nexpectIncludes(appDelegate, 'makeHeadroomGain', 'AppDelegate equalizer headroom helper')\nexpectIncludes(swiftPatch, 'makeHeadroomGain', 'Swift equalizer headroom helper')\nif (headroomMode === 'disabled') {\n  expectIncludes(appDelegate, 'return 1.0f;', 'AppDelegate disabled equalizer headroom')\n  expectIncludes(swiftPatch, 'return 1', 'Swift disabled equalizer headroom')\n}\nif (dynamicsMode === 'peakLimiter') {\n  expectIncludes(appDelegate, `_limiterThreshold = ${dynamicsThresholdLinear.toFixed(2)}f`, 'AppDelegate limiter threshold')\n  expectIncludes(appDelegate, `(${dynamicsAttack.toFixed(3)}f * (float)sampleRate)`, 'AppDelegate limiter attack')\n  expectIncludes(appDelegate, `(${dynamicsRelease.toFixed(2)}f * (float)sampleRate)`, 'AppDelegate limiter release')\n  expectIncludes(appDelegate, 'targetGain = _limiterThreshold / peak;', 'AppDelegate limiter gain reduction')\n  expectIncludes(swiftPatch, `private let limiterThreshold: Float = ${dynamicsThresholdLinear.toFixed(2)}`, 'Swift limiter threshold')\n  expectIncludes(swiftPatch, `${dynamicsAttack.toFixed(3)} * Float(sampleRate)`, 'Swift limiter attack')\n  expectIncludes(swiftPatch, `${dynamicsRelease.toFixed(2)} * Float(sampleRate)`, 'Swift limiter release')\n  expectIncludes(swiftPatch, 'targetGain = limiterThreshold / peak', 'Swift limiter gain reduction')\n}\n\nexpectCountAtLeast(appDelegate, new RegExp(`LXSoundEffectClampFloatValue\\\\([^\\\\n]+${pitchDefault.toFixed(1)}f, ${pitchMin.toFixed(1)}f, ${pitchMax.toFixed(1)}f\\\\)`, 'g'), 2, 'AppDelegate pitch clamp range')\nexpectIncludes(swiftPatch, `pitchPlaybackRate: clampedFloat(pitchInfo?[\"playbackRate\"], defaultValue: ${pitchDefault}, minValue: ${pitchMin}, maxValue: ${pitchMax})`, 'Swift pitch clamp range')\n\nexpectOrdered(\n  appDelegate,\n  [\n    'equalizerProcessor->processPCMChannels',\n    'pitchProcessor->processPCMChannels',\n    'convolutionProcessor->processPCMChannels',\n    'dynamicsProcessor->processPCMChannels',\n    'pannerProcessor->processPCMChannels',\n  ],\n  'AppDelegate processing order',\n)\n\nexpectOrdered(\n  swiftPatch,\n  [\n    'processEqualizer(samples[channel], channel: channel)',\n    'processPitch(&samples',\n    'processConvolution(&samples',\n    'processDynamics(&samples',\n    'applyPanner(to: &samples',\n  ],\n  'Swift processing order',\n)\n\nif (errors.length) {\n  console.error('Sound effect DSP profile check failed.')\n  for (const error of errors) console.error(`- ${error}`)\n  process.exit(1)\n}\n\nconsole.log('Sound effect DSP profile check passed.')\n" },
  { n: "check-button-opacity-coverage.js", s: "/**\n * 「按钮透明度」(theme.buttonOpacity) 覆盖面回归。\n *\n * 用户原话：\n *   「例如推荐中，酷我音乐、酷狗音乐、企鹅音乐、每日推荐、歌单内的最新最热以及默认和\n *     下面内容等类似按钮部位，它的底面透明度不会因为设置中的按钮透明度来改变，\n *     这些按钮有很多，请恢复」\n *   「主题设置中 TAB 栏距离、按钮透明度、背景模糊度、背景图片不透明度的进度条背景\n *     透明度，需要通过按钮透明度来控制（目前不受影响）」\n *\n * 需求口径：0-100，100 = 不透明（默认），0 = 底面/边框全透明**只剩文字**。\n * 实现口径：只能改颜色自身的 alpha（applyOpacity(颜色, buttonOpacity)），\n *           **不能**用容器 style.opacity —— 那会把文字一起淡掉，与需求相反。\n *\n * 本脚本钉死四条不变量：\n *   A. 纯按钮令牌 c-button-background / -active / -selected **不允许**再被当作\n *      底色/边框色直接使用（必须走 applyOpacity）——这是「按钮透明度漏接」的机器可判定形式。\n *   B. 用了 applyOpacity / useSettingValue('theme.buttonOpacity') 的文件必须真的 import，\n *      且必须声明过 const buttonOpacity = useSettingValue('theme.buttonOpacity')。\n *   C. 用户点名的表面（推荐平台胶囊、每日推荐卡、歌单最新最热/默认标签、歌单详情三键、\n *      详情页操作栏、四个主题滑条）必须仍在接线状态。\n *   D. 反例自检：把任一接线拆掉，本脚本必须判不合格（防止脚本自己退化成永真）。\n *\n * 运行：node scripts/check-button-opacity-coverage.js\n *\n * 【第 68 轮第 1 条】2026-10-12 变更 —— 用户原话：\n *   「…正在播放的音乐、长按多选的音乐以及下面的单选、区间、下载、全选、取消列的背景透明度\n *     需单独可调，调节滑块放在主题设置的按钮透明度下面…」\n * 多选选择栏的**条体**（底色 / 边框）从「按钮透明度」改挂新滑杆\n * theme.songHighlightOpacity（另见 check-song-highlight-opacity.js）；条内两颗模式芯片\n * （单选 / 区间）仍属按钮族，继续跟 theme.buttonOpacity。E 段因此在本轮补上 must / mustNot /\n * 反向三组判定，本文件其余段（A/B/C/D）口径不变。\n */\n\nconst fs = require('fs')\nconst path = require('path')\n\nconst ROOT = path.resolve(__dirname, '..')\nconst read = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8')\n\n// ---------------------------------------------------------------------------\n// 扫描 src/ 下所有 ts/tsx/js\n// ---------------------------------------------------------------------------\n// 注意：本仓脚本跑在 Electron-as-node 迷你运行器里，readdirSync 不支持 withFileTypes，\n// 一律用 readdirSync + statSync 判断目录。\nconst walk = (dir, out = []) => {\n  for (const name of fs.readdirSync(dir)) {\n    const full = path.join(dir, name)\n    if (fs.statSync(full).isDirectory()) walk(full, out)\n    else if (/\\.(ts|tsx|js|jsx)$/.test(name)) out.push(full)\n  }\n  return out\n}\n\n/**\n * 去掉注释但**保留行号**（块注释整段替换为同数量空白的换行），\n * 否则「文档注释里写的 applyOpacity(color, 100)」会被误判成写死常量。\n */\nconst stripComments = (t) =>\n  t\n    .replace(/\\/\\*[\\s\\S]*?\\*\\//g, (m) => m.replace(/[^\\n]/g, ' '))\n    .replace(/(^|[^:])\\/\\/[^\\n]*/gm, '$1')\n\nconst SRC = path.join(ROOT, 'src')\nconst rel = (f) => path.relative(ROOT, f).split(path.sep).join('/')\nconst FILES = walk(SRC).map((f) => ({ path: rel(f), text: fs.readFileSync(f, 'utf8') }))\nconst byPath = {}\nfor (const f of FILES) byPath[f.path] = f.text\n\n// ---------------------------------------------------------------------------\n// 判定\n// ---------------------------------------------------------------------------\n\n// A. 纯按钮令牌被直接当底色/边框色。\n//    判定按「行」：去注释后只要某行出现 theme['c-button-background...'] 的**值引用**，\n//    该行（或紧邻前后两行，容忍 applyOpacity( 换行书写）就必须出现 applyOpacity。\n//    为什么按行而不是按 `xxx: theme[...]`：\n//      三元分支 `backgroundColor: cond ? theme['c-button-background-active'] : theme['c-button-background']`\n//      在 `backgroundColor:` 后面跟的是条件表达式，属性名正则抓不到 —— 正是 MusicAddModal /\n//      MusicMultiAddModal 里 7 颗「歌单类型切换」按钮漏接的形态（第 3 批才发现）。\n//    不会误报的地方：主题定义表 `'c-button-background': theme[...]` 是「键」不是值引用；\n//    `Object.keys(theme).includes('c-button-background')` 是字符串字面量。\nconst RAW_BUTTON_TOKEN_LINE = /theme\\['c-button-background(-active|-selected|-hover)?'\\]/\n\nconst checkRawButtonTokens = (files) => {\n  const hits = []\n  for (const f of files) {\n    const lines = stripComments(f.text).split('\\n')\n    lines.forEach((line, i) => {\n      if (!RAW_BUTTON_TOKEN_LINE.test(line)) return\n      const around = [lines[i - 2], lines[i - 1], line, lines[i + 1], lines[i + 2]].join(' ')\n      if (/applyOpacity\\s*\\(/.test(around)) return\n      hits.push(`${f.path}:${i + 1}  ${line.trim().slice(0, 120)}`)\n    })\n  }\n  return hits\n}\n\n// B. import / 声明完整性\nconst checkImports = (files) => {\n  const hits = []\n  for (const f of files) {\n    const code = stripComments(f.text)\n    const usesApply = /applyOpacity\\s*\\(/.test(code)\n    const hasApplyImport = /import\\s*\\{[^}]*\\bapplyOpacity\\b[^}]*\\}\\s*from\\s*'@\\/utils\\/colorOpacity'/.test(code)\n    if (usesApply && !hasApplyImport) hits.push(`${f.path} 用了 applyOpacity 但没有 import { applyOpacity } from '@/utils/colorOpacity'`)\n\n    const hasHookImport = /import\\s*\\{[^}]*\\buseSettingValue\\b[^}]*\\}\\s*from\\s*'@\\/store\\/setting\\/hook'/.test(code)\n    const declares = /const\\s+buttonOpacity\\s*=\\s*useSettingValue\\(\\s*'theme\\.buttonOpacity'\\s*\\)/.test(code)\n    // 只要用到 buttonOpacity 这个变量，就必须来自设置 hook（防「声明被改成常量 100」「在回调里用变量」）。\n    // 先剔掉设置键字符串 'theme.buttonOpacity' —— 配置表 / 类型联合里出现的是键名，不是变量。\n    const codeNoKey = code.replace(/['\"]theme\\.buttonOpacity['\"]/g, '')\n    if (/\\bbuttonOpacity\\b/.test(codeNoKey) && !declares) {\n      hits.push(`${f.path} 用了 buttonOpacity 但没有 const buttonOpacity = useSettingValue('theme.buttonOpacity')（写死常量？或在回调里？）`)\n    }\n    if (/useSettingValue\\(\\s*'theme\\.buttonOpacity'\\s*\\)/.test(code) && !hasHookImport) {\n      hits.push(`${f.path} 用了 useSettingValue('theme.buttonOpacity') 但没有 import { useSettingValue } from '@/store/setting/hook'`)\n    }\n\n    // 反向：applyOpacity 第二个参数必须是 buttonOpacity 之类的透明度变量，不能是常量 100\n    const applied = code.match(/applyOpacity\\([^)]*,\\s*([^)]*?)\\)/g) || []\n    for (const call of applied) {\n      if (/,\\s*\\d+\\s*\\)\\s*$/.test(call)) hits.push(`${f.path} applyOpacity 第二参写死为常量（不会随设置变化）：${call.slice(0, 100)}`)\n    }\n  }\n  return hits\n}\n\n// C. 用户点名表面仍在接线\nconst REQUIRED = [\n  ['src/components/home/PlatformChips.tsx', '推荐页平台胶囊（酷我/酷狗/企鹅）'],\n  ['src/components/home/DailyRecommendCard.tsx', '每日推荐卡'],\n  ['src/screens/Home/Views/SongList/HeaderBar/SortTab.tsx', '歌单「最新/最热/默认」排序'],\n  ['src/screens/Home/Views/SongList/HeaderBar/TagRows.tsx', '歌单标签行'],\n  ['src/screens/SonglistDetail/ActionBar.tsx', '歌单详情「播放全部/收藏歌单/返回」'],\n  ['src/components/DetailActionBar.tsx', '详情页操作栏「播放全部/返回」'],\n  ['src/screens/Home/Views/Setting/components/Slider.tsx', '主题设置四个滑条的轨道'],\n  ['src/components/common/ButtonPrimary.tsx', '通用主按钮'],\n  ['src/components/common/ConfirmAlert.tsx', '通用确认框'],\n  ['src/components/MusicAddModal/MusicAddModal.tsx', '添加歌曲弹窗「本地/网易/QQ/酷狗歌单」四颗切换按钮'],\n  ['src/components/MusicMultiAddModal/MusicMultiAddModal.tsx', '批量添加弹窗「本地/网易/QQ歌单」三颗切换按钮'],\n  ['src/components/MusicAddModal/List.tsx', '「新建歌单」虚线按钮'],\n  ['src/components/MusicMultiAddModal/List.tsx', '「新建歌单」虚线按钮'],\n  ['src/screens/Home/Views/PlayHistory/index.tsx', '播放历史页日期栏与日期选择弹层按钮'],\n  // 【第 46 轮·图二/图三】用户原话：「播放历史界面，长按歌曲后出现的选择栏，可以到主题设置的\n  // 按钮透明度进行设置」——长按浮出的多选选择栏（单选 / 区间 / 下载 / 全选 / 取消）此前只有\n  // 「单选 / 区间」两颗芯片跟设置，整条栏的底色 / 边框是不透明的（歌单版更是把底色注释掉了、\n  // 只剩一条不透明底边框），于是整条栏看起来不受「按钮透明度」影响。\n  ['src/components/OnlineList/MultipleModeBar.tsx', '播放历史 / 在线列表长按浮出的多选选择栏'],\n  ['src/screens/Home/Views/Mylist/MusicList/MultipleModeBar.tsx', '歌单长按浮出的多选选择栏'],\n]\n\nconst checkRequired = (files) => {\n  const get = (p) => {\n    const hit = files.find((f) => f.path === p)\n    return hit && hit.text\n  }\n  const hits = []\n  for (const [file, what] of REQUIRED) {\n    const text = get(file)\n    if (!text) { hits.push(`${what}：文件不存在 ${file}`); continue }\n    const wired = /applyOpacity\\([^)]*buttonOpacity\\s*\\)/.test(text) && /useSettingValue\\(\\s*'theme\\.buttonOpacity'\\s*\\)/.test(text)\n    if (!wired) hits.push(`${what}：${file} 未接 applyOpacity(..., buttonOpacity)`)\n  }\n  // 轨道这两条单独钉：底槽与填充都要跟着淡\n  const slider = get('src/screens/Home/Views/Setting/components/Slider.tsx') || ''\n  if (!/applyOpacity\\(theme\\['c-button-background'\\]/.test(slider)) hits.push('四个滑条的轨道底色未随按钮透明度（Slider.tsx）')\n  if (!/applyOpacity\\(theme\\['c-button-background-active'\\]/.test(slider)) hits.push('四个滑条的已选填充未随按钮透明度（Slider.tsx）')\n  // 胶囊/tab 类底色令牌同样要淡\n  for (const file of ['src/components/home/PlatformChips.tsx', 'src/screens/Home/Views/SongList/HeaderBar/SortTab.tsx']) {\n    const text = get(file) || ''\n    if (!/applyOpacity\\(/.test(text)) hits.push(`${file} 没有任何 applyOpacity 接线`)\n  }\n  return hits\n}\n\n// E. 【第 46 轮】长按歌曲后浮出的「多选选择栏」：整条栏都要跟着透明度设置走。\n//    C 只检查「文件里存在 applyOpacity(..., buttonOpacity)」——两颗模式芯片早就满足它，\n//    而条容器本体的底色 / 边框仍是不透明色，用户看到的正是「这条栏不受透明度设置影响」。\n//    这里逐串钉死条容器那几行（整条栏一起淡）。\n//    【第 68 轮第 1 条】条容器本体那一档从「按钮透明度」改挂「歌曲高亮透明度」\n//    （用户原话：「…以及下面的单选、区间、下载、全选、取消列的背景透明度需单独可调」）：\n//      · must    —— 条体底色 / 边框必须成对出现 songHighlightOpacity；\n//      · mustNot —— 条体不得再挂 buttonOpacity（芯片那两颗仍是按钮族，不在此列）。\nconst checkMultiSelectBarOpacity = (files) => {\n  const get = (p) => {\n    const hit = files.find((f) => f.path === p)\n    return hit && hit.text\n  }\n  const hits = []\n  const need = (file, what, subs) => {\n    const raw = get(file)\n    if (!raw) { hits.push(`${what}：文件不存在 ${file}`); return }\n    const text = stripComments(raw)\n    for (const s of subs) {\n      if (!text.includes(s)) hits.push(`${what}（${file}）缺 ${s} —— 选择栏这一处又变回不透明 / 不跟设置`)\n    }\n  }\n  const forbid = (file, what, subs) => {\n    const raw = get(file)\n    if (!raw) return\n    const text = stripComments(raw)\n    for (const s of subs) {\n      if (text.includes(s)) hits.push(`${what}（${file}）条体又挂回按钮透明度（${s}）—— 第 68 轮第 1 条要求它与按钮透明度互相独立`)\n    }\n  }\n  need('src/components/OnlineList/MultipleModeBar.tsx', '在线列表多选选择栏条体', [\n    \"backgroundColor: applyOpacity(theme['c-content-background'], songHighlightOpacity),\",\n    \"borderColor: applyOpacity(theme['c-border-background'], songHighlightOpacity),\",\n  ])\n  forbid('src/components/OnlineList/MultipleModeBar.tsx', '在线列表多选选择栏条体', [\n    \"backgroundColor: applyOpacity(theme['c-content-background'], buttonOpacity),\",\n    \"borderColor: applyOpacity(theme['c-border-background'], buttonOpacity),\",\n  ])\n  need('src/screens/Home/Views/Mylist/MusicList/MultipleModeBar.tsx', '歌单多选选择栏条体', [\n    \"borderBottomColor: applyOpacity(theme['c-border-background'], songHighlightOpacity),\",\n  ])\n  forbid('src/screens/Home/Views/Mylist/MusicList/MultipleModeBar.tsx', '歌单多选选择栏条体', [\n    \"borderBottomColor: applyOpacity(theme['c-border-background'], buttonOpacity),\",\n  ])\n  // 条内两颗模式芯片仍是「按钮」族：必须继续跟按钮透明度（别把整条栏一刀切过去）\n  need('src/components/OnlineList/MultipleModeBar.tsx', '在线列表多选选择栏芯片', [\n    \"? applyOpacity(theme['c-button-background'], buttonOpacity)\",\n  ])\n  need('src/screens/Home/Views/Mylist/MusicList/MultipleModeBar.tsx', '歌单多选选择栏芯片', [\n    \"? applyOpacity(theme['c-button-background'], buttonOpacity)\",\n  ])\n  return hits\n}\n\n// ---------------------------------------------------------------------------\n// 运行\n// ---------------------------------------------------------------------------\nconst assertions = []\nlet failed = 0\n\nassertions.push({\n  name: 'A 纯按钮令牌不再被直接当底色/边框色（必须走 applyOpacity）',\n  hits: checkRawButtonTokens(FILES),\n})\nassertions.push({\n  name: 'B applyOpacity / buttonOpacity 的 import 与声明完整',\n  hits: checkImports(FILES),\n})\nassertions.push({\n  name: 'C 用户点名的按钮表面仍在接线状态',\n  hits: checkRequired(FILES),\n})\nassertions.push({\n  name: 'E 长按浮出的多选选择栏：条体（底色 / 边框）随「歌曲高亮透明度」（第 68 轮第 1 条），条内芯片仍随按钮透明度',\n  hits: checkMultiSelectBarOpacity(FILES),\n})\n\n// D. 反例自检\nconst tamperFiles = (targetPath, replace) => FILES.map((f) => (f.path === targetPath ? { ...f, text: replace(f.text) } : f))\n\nconst counterExamples = []\nconst CE = (name, files, fn, expectSubstr) => {\n  const hits = fn(files)\n  const ok = hits.some((h) => h.includes(expectSubstr))\n  counterExamples.push({ name, ok, detail: hits.join('；') })\n}\n\nCE('C1 纯按钮令牌退回直接写死（通用主按钮）', tamperFiles('src/components/common/ButtonPrimary.tsx',\n  (t) => t.replace(/backgroundColor: applyOpacity\\(theme\\['c-button-background'\\], buttonOpacity\\)/, \"backgroundColor: theme['c-button-background']\")),\ncheckRawButtonTokens, 'src/components/common/ButtonPrimary.tsx')\n\nCE('C2 删掉 applyOpacity 的 import', tamperFiles('src/components/common/ConfirmAlert.tsx',\n  (t) => t.replace(/^.*import\\s*\\{[^}]*applyOpacity[^}]*\\}.*$/m, '')),\ncheckImports, 'ConfirmAlert.tsx 用了 applyOpacity 但没有 import')\n\nCE('C3 buttonOpacity 常量改成写死 100', tamperFiles('src/screens/SonglistDetail/ActionBar.tsx',\n  (t) => t.replace(/const buttonOpacity = useSettingValue\\('theme\\.buttonOpacity'\\)/, 'const buttonOpacity = 100')),\ncheckImports, '用了 buttonOpacity 但没有 const buttonOpacity')\n\nCE('C4 平台胶囊整段拆掉接线（文件退化为不读设置）', tamperFiles('src/components/home/PlatformChips.tsx',\n  (t) => t.replace(/const buttonOpacity = useSettingValue\\('theme\\.buttonOpacity'\\)/, 'const buttonOpacity = 100')\n    .replace(/applyOpacity\\(([^,]+), buttonOpacity\\)/g, '$1')),\ncheckRequired, '推荐页平台胶囊')\n\nCE('C5 滑条轨道去掉按钮透明度（回到需求点名的缺陷）', tamperFiles('src/screens/Home/Views/Setting/components/Slider.tsx',\n  (t) => t.replace(/applyOpacity\\(theme\\['c-button-background'\\]/, \"String(theme['c-button-background'])\")),\ncheckRequired, '轨道底色未随按钮透明度')\n\n// 2026-10-02：「播放全部」底色由 c-primary 改为 c-primary-background（需求：改用歌单详情页\n// 那套「主色文字 + 淡灰底」），反例的替换目标同步跟着改——否则 replace 找不到匹配、静默失败，\n// 本反例会「没拦住」而脚本自己不知道。\nCE('C6 applyOpacity 第二参写死常量', tamperFiles('src/components/DetailActionBar.tsx',\n  (t) => t.replace(/applyOpacity\\(theme\\['c-primary-background'\\], buttonOpacity\\)/, \"applyOpacity(theme['c-primary-background'], 100)\")),\ncheckImports, '第二参写死为常量')\n\n// C7 对应「第三批才发现的形态」：三元分支里的按钮令牌退回裸用（属性名正则抓不到，按行判定能抓）\nCE('C7 三元分支里的按钮令牌退回裸用（歌单类型切换按钮）', tamperFiles('src/components/MusicAddModal/MusicAddModal.tsx',\n  (t) => t.replace(/\\? applyOpacity\\(theme\\['c-button-background-active'\\], buttonOpacity\\) : applyOpacity\\(theme\\['c-button-background'\\], buttonOpacity\\)/,\n    \"? theme['c-button-background-active'] : theme['c-button-background']\")),\ncheckRawButtonTokens, 'MusicAddModal.tsx')\n\n// 【第 46 轮】选择栏条体退回不透明（两颗模式芯片仍接着线 ⇒ C 抓不到，必须由 E 拦）\nCE('E1 在线列表选择栏条体退回不透明底色', tamperFiles('src/components/OnlineList/MultipleModeBar.tsx',\n  (t) => t.replace(\"backgroundColor: applyOpacity(theme['c-content-background'], songHighlightOpacity),\",\n    \"backgroundColor: theme['c-content-background'],\")),\ncheckMultiSelectBarOpacity, '在线列表多选选择栏条体')\n\nCE('E2 歌单选择栏条体边框退回不透明', tamperFiles('src/screens/Home/Views/Mylist/MusicList/MultipleModeBar.tsx',\n  (t) => t.replace(\"borderBottomColor: applyOpacity(theme['c-border-background'], songHighlightOpacity),\",\n    \"borderBottomColor: theme['c-border-background'],\")),\ncheckMultiSelectBarOpacity, '歌单多选选择栏条体')\n\n// 【第 68 轮第 1 条】条体又挂回「按钮透明度」（两个设置重新绑死）——条体那串必须被 forbid 拦下\nCE('E3 在线列表选择栏条体又挂回按钮透明度', tamperFiles('src/components/OnlineList/MultipleModeBar.tsx',\n  (t) => t.replace(\"backgroundColor: applyOpacity(theme['c-content-background'], songHighlightOpacity),\",\n    \"backgroundColor: applyOpacity(theme['c-content-background'], buttonOpacity),\")),\ncheckMultiSelectBarOpacity, '又挂回按钮透明度')\n\nCE('E4 歌单选择栏条体又挂回按钮透明度', tamperFiles('src/screens/Home/Views/Mylist/MusicList/MultipleModeBar.tsx',\n  (t) => t.replace(\"borderBottomColor: applyOpacity(theme['c-border-background'], songHighlightOpacity),\",\n    \"borderBottomColor: applyOpacity(theme['c-border-background'], buttonOpacity),\")),\ncheckMultiSelectBarOpacity, '又挂回按钮透明度')\n\n// 【第 68 轮第 1 条】反向：条内两颗模式芯片被一刀切到「歌曲高亮透明度」（按钮族被错挂）\nCE('E5 条内模式芯片被错挂到歌曲高亮透明度', tamperFiles('src/components/OnlineList/MultipleModeBar.tsx',\n  (t) => t.replace(/\\? applyOpacity\\(theme\\['c-button-background'\\], buttonOpacity\\)/g,\n    \"? applyOpacity(theme['c-button-background'], songHighlightOpacity)\")),\ncheckMultiSelectBarOpacity, '在线列表多选选择栏芯片')\n\n// ---------------------------------------------------------------------------\n// 输出\n// ---------------------------------------------------------------------------\nconsole.log('='.repeat(92))\nconsole.log('按钮透明度（theme.buttonOpacity）覆盖面回归')\nconsole.log('='.repeat(92))\nconsole.log('  A 纯按钮令牌必须走 applyOpacity（不能直接当底色/边框色）')\nconsole.log('  B import / const buttonOpacity 声明完整，且第二参不是写死常量')\nconsole.log('  C 用户点名的表面（推荐胶囊 / 每日推荐 / 最新最热 / 歌单三键 / 详情栏 / 四个滑条）仍在接线')\nconsole.log('  E 长按浮出的多选选择栏：条体随「歌曲高亮透明度」，条内芯片仍随按钮透明度（第 68 轮第 1 条）')\nconsole.log()\n\nconsole.log('='.repeat(92))\nconsole.log('断言')\nconsole.log('='.repeat(92))\nfor (const a of assertions) {\n  const ok = a.hits.length === 0\n  if (!ok) failed++\n  console.log(`  ${ok ? '✅' : '❌'}  ${a.name}`)\n  for (const h of a.hits.slice(0, 40)) console.log(`        ${h}`)\n  if (a.hits.length > 40) console.log(`        ...（共 ${a.hits.length} 处）`)\n}\n\nconsole.log()\nconsole.log('='.repeat(92))\nconsole.log('反例自检（接线被拆掉时必须拦下）')\nconsole.log('='.repeat(92))\nfor (const c of counterExamples) {\n  if (!c.ok) failed++\n  console.log(`  ${c.ok ? '✅' : '❌'}  ${c.name}${c.ok ? ' —— 已拦下' : '   ← 没拦住：' + c.detail}`)\n}\n\nconst okCount = assertions.filter((a) => a.hits.length === 0).length\nconst ceOk = counterExamples.filter((c) => c.ok).length\nconsole.log()\nconsole.log(`结果：断言 ${okCount}/${assertions.length} 通过；反例 ${ceOk}/${counterExamples.length} 拦下`)\nprocess.exit(failed ? 1 : 0)\n" },
  { n: "check-song-highlight-opacity.js", s: "#!/usr/bin/env node\n/**\n * check-song-highlight-opacity.js —— 「歌曲高亮透明度」(theme.songHighlightOpacity) 覆盖面回归。\n *\n * 【第 68 轮第 1 条】2026-10-12 用户原话：\n *   「如图一至二：正在播放的音乐、长按多选的音乐以及下面的单选、区间、下载、全选、取消列的\n *     背景透明度需单独可调，调节滑块放在主题设置的按钮透明度下面，调节透明度 0-100，\n *     配置范围是所有包含上面要求的地方」\n *\n * 需求口径：\n *   · 一根**新**滑杆，位置紧跟在「按钮透明度」(theme.buttonOpacity) 下面；\n *   · 0-100，100 = 与主题原色一致（默认）；0 = 高亮底色完全消失（文字 / 图标 / 按钮不受影响）；\n *   · 覆盖范围 = **所有**出现这三类高亮面的地方：\n *       ① 正在播放的那一行；② 长按多选后被选中的行；③ 长按浮出的多选操作栏（单选 / 区间 /\n *       下载 / 全选 / 取消）的条体。\n *   · 与「按钮透明度」**互相独立** —— 第 46～67 轮这几处搭在按钮透明度上，本轮拆开。\n *\n * 实现口径：只改颜色自身的 alpha（applyOpacity(颜色, songHighlightOpacity)），\n *           **不能**用容器 style.opacity —— 那会把歌名/封面/图标一起淡掉，与「只调背景」相反。\n *           （多选栏的容器 opacity 已被入场动画占着，更不能再叠。）\n *\n * 本脚本钉死三组不变量：\n *   A. 设置项本身落地齐全：默认值 / SliderRow 联合类型 / 两根 i18n 键 / 新组件 /\n *      主题设置里的**顺序**（ButtonOpacity → SongHighlightOpacity → ButtonRadius）\n *      / 0-100 步进 1（不传 minimumValue·maximumValue·step，用 SliderRow 的默认口径）。\n *   B. 七个消费点（5 行 + 2 条栏）都订阅了新设置，且高亮那一档与新设置成对出现、\n *      不再跟 buttonOpacity。\n *   C. 全仓扫描兜底：「高亮 token + buttonOpacity」这一对被拆开的旧挂法不得在任何地方复活。\n *\n * 运行：node scripts/check-song-highlight-opacity.js\n * 退出码：不变量全过、且全部反例被拦下时为 0，否则 1。\n */\n'use strict'\n\nconst fs = require('fs')\nconst path = require('path')\n\nconst ROOT = path.resolve(__dirname, '..')\nconst read = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8').replace(/\\r\\n/g, '\\n')\nconst stripComments = (src) => src.replace(/\\/\\*[\\s\\S]*?\\*\\//g, '').replace(/\\/\\/[^\\n]*/g, '')\n\nconst SETTING_KEY = 'theme.songHighlightOpacity'\nconst PAIR = \"applyOpacity(theme['c-list-item-background-selected'], songHighlightOpacity)\"\nconst OLD_PAIR = \"applyOpacity(theme['c-list-item-background-selected'], buttonOpacity)\"\n\nconst F = {\n  defaultSetting: 'src/config/defaultSetting.ts',\n  sliderRow: 'src/screens/Home/Views/Setting/components/SliderRow.tsx',\n  i18n: 'src/lang/zh-cn.json',\n  component: 'src/screens/Home/Views/Setting/settings/Theme/SongHighlightOpacity.tsx',\n  themeScreen: 'src/screens/Home/Views/Setting/settings/ThemeScreen.tsx',\n}\n\n// 五个歌曲行 + 两条多选栏（= 全工程「isPlaying / isSelected 决定整行底色」与\n// 「长按后浮出的那条操作栏」的全部落点；第 46 轮已逐个核过一遍）。\nconst CONSUMERS = [\n  {\n    file: 'src/components/OnlineList/ListItem.tsx',\n    label: '在线列表（歌单详情 / 搜索 / 排行榜 / 播放历史…）—— 三类高亮全在此覆盖',\n    must: [PAIR],\n    mustNot: [OLD_PAIR],\n  },\n  {\n    file: 'src/screens/Home/Views/Mylist/MusicList/ListItem.tsx',\n    label: '试听列表',\n    must: [PAIR],\n    mustNot: [OLD_PAIR],\n  },\n  {\n    file: 'src/screens/Home/Views/Mylist/MyList/DuplicateMusic.tsx',\n    label: '重复歌曲弹窗',\n    must: [PAIR],\n    mustNot: [OLD_PAIR],\n  },\n  {\n    file: 'src/screens/Home/Views/LocalDownload/index.tsx',\n    label: '本地与下载（含批量选择浮动条所在页面）',\n    must: [PAIR],\n    mustNot: [OLD_PAIR],\n  },\n  {\n    file: 'src/screens/Home/Views/WebDAV/index.tsx',\n    label: 'WebDAV（播放中卡片的底色 + 边框两支都拆开了）',\n    must: [\n      \"? applyOpacity(theme['c-list-item-background-selected'], songHighlightOpacity)\",\n      \"? applyOpacity(theme['c-primary-background-active'], songHighlightOpacity)\",\n    ],\n    mustNot: [\n      \"applyOpacity(theme['c-list-item-background-selected'], buttonOpacity)\",\n      \"applyOpacity(theme['c-primary-background-active'], buttonOpacity)\",\n    ],\n  },\n  {\n    file: 'src/components/OnlineList/MultipleModeBar.tsx',\n    label: '在线列表多选操作栏（单选 / 区间 / 下载 / 全选 / 取消）条体',\n    must: [\n      \"backgroundColor: applyOpacity(theme['c-content-background'], songHighlightOpacity),\",\n      \"borderColor: applyOpacity(theme['c-border-background'], songHighlightOpacity),\",\n    ],\n    mustNot: [\n      \"backgroundColor: applyOpacity(theme['c-content-background'], buttonOpacity),\",\n      \"borderColor: applyOpacity(theme['c-border-background'], buttonOpacity),\",\n    ],\n  },\n  {\n    file: 'src/screens/Home/Views/Mylist/MusicList/MultipleModeBar.tsx',\n    label: '歌单多选操作栏条体（本组件条体只有底边框，底色那行早被注释掉）',\n    must: [\"borderBottomColor: applyOpacity(theme['c-border-background'], songHighlightOpacity),\"],\n    mustNot: [\"borderBottomColor: applyOpacity(theme['c-border-background'], buttonOpacity),\"],\n  },\n]\n\n// ---------------------------------------------------------------------------\n// A. 设置项本身落地齐全（少一处就是「滑杆不出现 / 出现但无效 / 文案是 key」）\n// ---------------------------------------------------------------------------\nconst checkSettingWiring = (files) => {\n  const hits = []\n  const get = (p) => files[p]\n\n  const def = get(F.defaultSetting)\n  if (def == null) hits.push(`文件不存在 ${F.defaultSetting}`)\n  else if (!stripComments(def).includes(`'${SETTING_KEY}': 100,`)) {\n    hits.push(`默认设置缺 '${SETTING_KEY}': 100（新滑杆没有默认值 ⇒ 首帧取值 undefined，高亮底色可能整片消失）`)\n  }\n\n  const sr = get(F.sliderRow)\n  if (sr == null) hits.push(`文件不存在 ${F.sliderRow}`)\n  else if (!stripComments(sr).includes(`| '${SETTING_KEY}'`)) {\n    hits.push(`SliderRow 的 settingKey 联合类型缺 | '${SETTING_KEY}'（TS 编译不过 / 组件无法复用该行）`)\n  }\n\n  const i18n = get(F.i18n)\n  if (i18n == null) hits.push(`文件不存在 ${F.i18n}`)\n  else {\n    for (const key of [\n      'setting_basic_theme_song_highlight_opacity',\n      'setting_basic_theme_song_highlight_opacity_desc',\n    ]) {\n      const re = new RegExp(`\"${key}\"\\\\s*:\\\\s*\"[^\"]+\"`)\n      if (!re.test(i18n)) hits.push(`i18n 缺键或值为空：${key}`)\n    }\n  }\n\n  const comp = get(F.component)\n  if (comp == null) {\n    hits.push(`文件不存在 ${F.component}（新滑杆组件没落地）`)\n  } else {\n    const c = stripComments(comp)\n    if (!c.includes(`useSettingValue('${SETTING_KEY}')`)) {\n      hits.push(`${F.component} 没有订阅 ${SETTING_KEY}（拖动后本行数值不跟手）`)\n    }\n    if (!c.includes(`settingKey=\"${SETTING_KEY}\"`)) {\n      hits.push(`${F.component} 没有把 settingKey 传到 SliderRow（写不到设置里，拖了白拖）`)\n    }\n    // 0-100、步进 1：本行不能覆盖 SliderRow 的默认口径\n    for (const bad of ['minimumValue', 'maximumValue', 'step=']) {\n      if (c.includes(bad)) {\n        hits.push(`${F.component} 自己传了 ${bad}（本轮口径是 0-100、步进 1，用 SliderRow 的默认值即可）`)\n      }\n    }\n    if (!/title=\\{[^}]*setting_basic_theme_song_highlight_opacity[^}]*\\}/.test(c)) {\n      hits.push(`${F.component} 标题没接 i18n 键 setting_basic_theme_song_highlight_opacity`)\n    }\n    if (!/desc=\\{[^}]*setting_basic_theme_song_highlight_opacity_desc[^}]*\\}/.test(c)) {\n      hits.push(`${F.component} 说明小字没接 i18n 键 setting_basic_theme_song_highlight_opacity_desc`)\n    }\n  }\n\n  const ts = get(F.themeScreen)\n  if (ts == null) hits.push(`文件不存在 ${F.themeScreen}`)\n  else {\n    const c = stripComments(ts)\n    if (!c.includes(\"import SongHighlightOpacity from './Theme/SongHighlightOpacity'\")) {\n      hits.push(`${F.themeScreen} 没有 import 新滑杆组件`)\n    }\n    const atNew = c.indexOf('<SongHighlightOpacity />')\n    const atBtn = c.indexOf('<ButtonOpacity />')\n    const atRadius = c.indexOf('<ButtonRadius />')\n    if (atNew < 0) {\n      hits.push(`${F.themeScreen} 没有渲染 <SongHighlightOpacity />（用户要的滑杆根本没出现在主题设置里）`)\n    } else if (atBtn < 0) {\n      hits.push(`${F.themeScreen} 找不到 <ButtonOpacity />（顺序锚点漂移，无法核对「放在按钮透明度下面」）`)\n    } else if (atNew < atBtn) {\n      hits.push(`${F.themeScreen} 新滑杆排在「按钮透明度」**上面**了（用户要的是紧跟它下面）`)\n    } else if (atRadius >= 0 && atNew > atRadius) {\n      hits.push(`${F.themeScreen} 新滑杆被排到「按钮圆角」下面了（应插在按钮透明度与按钮圆角之间）`)\n    }\n  }\n\n  return hits\n}\n\n// ---------------------------------------------------------------------------\n// B. 七个消费点：订阅 + 成对使用 + 不跟 buttonOpacity\n// ---------------------------------------------------------------------------\nconst checkConsumers = (files) => {\n  const hits = []\n  for (const c of CONSUMERS) {\n    const raw = files[c.file]\n    if (raw == null) {\n      hits.push(`${c.label}：文件不存在 ${c.file}`)\n      continue\n    }\n    const code = stripComments(raw)\n    if (!code.includes(`useSettingValue('${SETTING_KEY}')`)) {\n      hits.push(`${c.label}（${c.file}）没订阅 ${SETTING_KEY} —— 改这根滑杆时它不会重渲染，要点一下才刷新`)\n    }\n    for (const s of c.must) {\n      if (!code.includes(s)) hits.push(`${c.label}（${c.file}）缺 ${s} —— 高亮这一档脱离了「歌曲高亮透明度」`)\n    }\n    for (const s of c.mustNot) {\n      if (code.includes(s)) hits.push(`${c.label}（${c.file}）又挂回按钮透明度（${s}）—— 第 68 轮第 1 条要求两个设置互相独立`)\n    }\n  }\n  return hits\n}\n\n// ---------------------------------------------------------------------------\n// C. 全仓扫描兜底：被拆开的旧挂法不得在任何地方复活\n//    （只扫 src 下的 .ts/.tsx；node_modules 等不在 src 里）\n// ---------------------------------------------------------------------------\n// 注意：本仓脚本跑在浏览器迷你运行器里，`readdirSync(dir, { withFileTypes: true })` 的\n// Dirent.isDirectory() 被实现成了「恒真」——遍历会把文件当目录再 readdir 一次，报\n// `ENOENT: scandir '/src/app.ts'`（同 check-button-opacity-coverage.js / sim-power-drain.js\n// 里的同一坑）。所以这里一律 readdirSync + statSync 判目录，并且 .ts/.tsx 直接当文件收走，\n// 双保险：**不信任 withFileTypes**。\nconst walkSrc = (dir, out) => {\n  for (const name of fs.readdirSync(dir)) {\n    const full = path.join(dir, name)\n    if (/\\.(ts|tsx)$/.test(name)) {\n      out.push(full)\n      continue\n    }\n    let isDir = false\n    try {\n      isDir = fs.statSync(full).isDirectory()\n    } catch (e) {\n      isDir = false\n    }\n    if (isDir) walkSrc(full, out)\n  }\n  return out\n}\n\n// extra：反例用「虚拟文件」（{ rel, text }），不必真往 src 里写东西再删。\nconst checkGlobalScan = (extra) => {\n  const hits = []\n  const list = walkSrc(path.join(ROOT, 'src'), []).map((full) => ({ full, text: null }))\n  if (extra) list.push({ full: path.join(ROOT, extra.rel), text: extra.text })\n  for (const { full, text } of list) {\n    const rel = path.relative(ROOT, full).split(path.sep).join('/')\n    const code = stripComments(text == null ? fs.readFileSync(full, 'utf8').replace(/\\r\\n/g, '\\n') : text)\n    if (code.includes(OLD_PAIR)) {\n      hits.push(`${rel} 里还有「高亮 token + buttonOpacity」的旧挂法（第 68 轮第 1 条已把高亮档拆到 ${SETTING_KEY}）`)\n    }\n  }\n  return hits\n}\n\n// ---------------------------------------------------------------------------\n// 反例（对篡改后的源码跑同一套判断，必须被拦下）\n// ---------------------------------------------------------------------------\n\nconst tamper = (src, find, replace) => {\n  if (!src.includes(find)) throw new Error(`tamper 锚点未命中: ${find.slice(0, 60)}`)\n  return src.split(find).join(replace)\n}\n\nconst runCounterExamples = (REAL) => {\n  const results = []\n  const check = (name, fn, expectReasonSubstr) => {\n    let hits = []\n    try {\n      hits = fn()\n    } catch (e) {\n      results.push({ name, ok: false, detail: `抛异常: ${e.message}` })\n      return\n    }\n    const hit = hits.some((r) => r.includes(expectReasonSubstr))\n    results.push({ name, ok: hit, detail: hit ? '已拦下' : `未拦下（hits=${JSON.stringify(hits)}）` })\n  }\n  const withFiles = (over) => {\n    const files = {}\n    for (const [k, p] of Object.entries(F)) files[p] = REAL.files[p]\n    for (const [p, text] of Object.entries(over)) files[p] = text\n    return files\n  }\n  const withConsumer = (p, text) => {\n    const files = {}\n    for (const c of CONSUMERS) files[c.file] = REAL.consumers[c.file]\n    files[p] = text\n    return files\n  }\n\n  // a1 默认值被删（首帧取值 undefined）\n  check('a1 默认设置缺 songHighlightOpacity', () => checkSettingWiring(withFiles({\n    [F.defaultSetting]: tamper(REAL.files[F.defaultSetting], `  '${SETTING_KEY}': 100,`, ''),\n  })), '默认设置缺')\n\n  // a2 滑杆被排到「按钮透明度」上面（用户要的位置）\n  check('a2 滑杆排到按钮透明度上面', () => checkSettingWiring(withFiles({\n    [F.themeScreen]: tamper(REAL.files[F.themeScreen],\n      \"      <ButtonOpacity />\\n      {/* 【第 68 轮】歌曲高亮（正在播放行 / 多选选中行 / 多选操作栏）底色不透明度，紧跟按钮透明度下面 */}\\n      <SongHighlightOpacity />\",\n      \"      <SongHighlightOpacity />\\n      {/* 【第 68 轮】歌曲高亮（正在播放行 / 多选选中行 / 多选操作栏）底色不透明度，紧跟按钮透明度下面 */}\\n      <ButtonOpacity />\"),\n  })), '排在「按钮透明度」**上面**了')\n\n  // a3 新组件忘了把 settingKey 传下去（拖了白拖）\n  check('a3 组件没传 settingKey', () => checkSettingWiring(withFiles({\n    [F.component]: tamper(REAL.files[F.component],\n      `      settingKey=\"${SETTING_KEY}\"\\n`, ''),\n  })), '没有把 settingKey 传到 SliderRow')\n\n  // a4 i18n 键缺失\n  check('a4 i18n 键缺失', () => checkSettingWiring(withFiles({\n    [F.i18n]: tamper(REAL.files[F.i18n],\n      '\"setting_basic_theme_song_highlight_opacity\": \"歌曲高亮透明度\",',\n      '\"setting_basic_theme_song_highlight_opacity_x\": \"歌曲高亮透明度\",'),\n  })), 'i18n 缺键')\n\n  // b1 在线列表高亮又挂回 buttonOpacity\n  check('b1 在线列表高亮挂回按钮透明度', () => checkConsumers(withConsumer(\n    'src/components/OnlineList/ListItem.tsx',\n    tamper(REAL.consumers['src/components/OnlineList/ListItem.tsx'], PAIR, OLD_PAIR),\n  )), '又挂回按钮透明度')\n\n  // b2 WebDAV 播放中边框挂回 buttonOpacity\n  check('b2 WebDAV 播放中边框挂回按钮透明度', () => checkConsumers(withConsumer(\n    'src/screens/Home/Views/WebDAV/index.tsx',\n    tamper(REAL.consumers['src/screens/Home/Views/WebDAV/index.tsx'],\n      \"? applyOpacity(theme['c-primary-background-active'], songHighlightOpacity)\",\n      \"? applyOpacity(theme['c-primary-background-active'], buttonOpacity)\"),\n  )), '又挂回按钮透明度')\n\n  // b3 多选栏没订阅新设置（条体写死）\n  check('b3 多选栏条体写死不透明', () => checkConsumers(withConsumer(\n    'src/components/OnlineList/MultipleModeBar.tsx',\n    tamper(REAL.consumers['src/components/OnlineList/MultipleModeBar.tsx'],\n      \"backgroundColor: applyOpacity(theme['c-content-background'], songHighlightOpacity),\",\n      \"backgroundColor: theme['c-content-background'],\"),\n  )), '缺 backgroundColor: applyOpacity')\n\n  // b4 歌单多选栏去掉订阅（写死 100）\n  check('b4 歌单多选栏不订阅新设置', () => checkConsumers(withConsumer(\n    'src/screens/Home/Views/Mylist/MusicList/MultipleModeBar.tsx',\n    tamper(REAL.consumers['src/screens/Home/Views/Mylist/MusicList/MultipleModeBar.tsx'],\n      `    const songHighlightOpacity = useSettingValue('${SETTING_KEY}')\\n`,\n      '    const songHighlightOpacity = 100\\n'),\n  )), '没订阅 theme.songHighlightOpacity')\n\n  // c1 旧挂法在别处复活（全仓扫描兜底）——喂一个虚拟的漏网文件，不落盘\n  check('c1 全仓扫描兜底', () => checkGlobalScan({\n    rel: 'src/__r68_scan_probe.tsx',\n    text: `export const x = ${OLD_PAIR}\\n`,\n  }), '旧挂法')\n\n  return results\n}\n\n// ---------------------------------------------------------------------------\n// 主流程\n// ---------------------------------------------------------------------------\nconsole.log('=== check-song-highlight-opacity ===')\nconsole.log('「歌曲高亮透明度」(theme.songHighlightOpacity)：设置落地 + 七个消费点 + 全仓兜底扫描')\nconsole.log()\n\nconst REAL = { files: {}, consumers: {} }\nfor (const p of Object.values(F)) REAL.files[p] = read(p)\nfor (const c of CONSUMERS) REAL.consumers[c.file] = read(c.file)\n\nconst assertions = [\n  { name: 'A 设置项落地齐全（默认值 / 联合类型 / i18n / 组件 / 顺序 / 0-100 步进 1）', hits: checkSettingWiring(REAL.files) },\n  { name: 'B 七个消费点（5 行 + 2 条多选栏）都订阅新设置且高亮档与它成对出现', hits: checkConsumers(REAL.consumers) },\n  { name: 'C 全仓扫描：高亮 token + buttonOpacity 的旧挂法不再出现', hits: checkGlobalScan() },\n]\n\nlet failed = 0\nfor (const a of assertions) {\n  const ok = a.hits.length === 0\n  if (!ok) failed++\n  console.log(`[${ok ? 'PASS' : 'FAIL'}] ${a.name}`)\n  for (const h of a.hits.slice(0, 40)) console.log(`        ${h}`)\n  if (a.hits.length > 40) console.log(`        ...（共 ${a.hits.length} 处）`)\n}\n\nconsole.log('\\n[反例自检]')\nconst ces = runCounterExamples(REAL)\nlet ceOk = 0\nfor (const r of ces) {\n  console.log(`  ${r.ok ? 'PASS' : 'FAIL'} ${r.name} —— ${r.detail}`)\n  if (r.ok) ceOk++\n}\n\nconst assertOk = assertions.filter((a) => a.hits.length === 0).length\nconsole.log(`\\n结果：断言 ${assertOk}/${assertions.length} 通过；反例 ${ceOk}/${ces.length} 拦下`)\nprocess.exit(failed || ceOk !== ces.length ? 1 : 0)\n" },
  { n: "check-button-radius-coverage.js", s: "/**\n * 「按钮圆角」(theme.buttonRadius) 接线覆盖面回归。\n *\n * 生效链路：theme.buttonRadius 是设置项（0 = 直角，100 = 半圆），useButtonRadius()\n * 订阅它并返回「按钮设计高度 → 半径」的换算函数。由于 createStyle 的样式在模块加载时\n * 固化，调用点必须再以**行内** style 覆盖 borderRadius 才能吃到设置：\n *\n *   const buttonRadius = useButtonRadius()                       // 订阅\n *   <View style={[styles.x, { borderRadius: buttonRadius(44) }]} // 行内覆盖(44 = 设计高度)\n *\n * 所以「设置里的按钮圆角能不能改到这个按钮」等价于「它所在文件有没有这套接线」。\n * 本脚本把这个要求变成可判定的不变量。\n *\n * 与同目录其它脚本的分工（本脚本不重复它们钉过的东西）：\n *   - sim-radius-tokens.js              钉设计令牌值（designRadius 4/4/8/12）与封面静态兜底值；\n *   - check-button-opacity-coverage.js  钉 theme.buttonOpacity 的接线面；\n *   - 本脚本                            只钉「按钮圆角的接线面」：import / 调用形态 / 行内覆盖 / 传参。\n *     C 段的 buttonRadius(70) 这类钉子是「接线传参」，不是 sim-radius-tokens.js 里的静态值。\n *\n * 四条不变量：\n *   A. 每个使用按钮底色令牌 c-button-background / -active / -selected 的 .tsx 文件，\n *      必须在本文件内接好 useButtonRadius（import + 调用 + 行内覆盖）。文件清单由扫描\n *      动态得出并逐个打印——新文件漏接、清单漂移都会被拦下。\n *      口径从严：令牌出现即视为「按钮族表面」；唯一的免检出口是 TOKEN_EXEMPT 里**具名**\n *      列出的文件（其令牌经复核不属本文件可控的按钮外观，理由写进名单并在代码里留注记）。\n *      绝不放开令牌判定本身：不在名单里的文件漏接一律照拦；名单条目一旦腐化（文件已\n *      不再用令牌）也会被反查拦下，逼着同步删除过期豁免。\n *   B. 每个调用 useButtonRadius() 的文件：import 必须在场且来自 '@/utils/buttonRadius'；\n *      每处调用都必须是 `const buttonRadius = useButtonRadius()` 形态、且声明行有缩进\n *      （去缩进 = 模块顶层 = 在组件外调用 hook，机器可判定）；import 了却一次不调 = 死 import，也拦。\n *   C. 用户点名的八类面（歌单封面 / 排行榜按钮 / 酷我音乐按钮 / 搜索页的搜索框 /\n *      搜索框下面的按钮 / 热门搜索下面的容器 / 历史搜索下面的容器 / 设置中所有的按钮）\n *      对应真实文件逐个断言接线在位，并钉住各点实际传参（buttonRadius(48) 等），\n *      防止「hook 还在、行内覆盖被删/被改数值」。\n *   D. 反例自检：10 条篡改（删 import / 删调用 / 删行内覆盖 / 挪出组件 / 来源改错 / 调用改名）\n *      必须被同一套函数拦下；**替换未命中同样判失败**（防反例老化成永真）。\n *\n * ⚠️ 纯静态断言：通过只说明这些调用点的接线文本在位；本工程没有 node/tsc/Xcode 工具链，\n *    不代表能编译、不代表真机观感正确。真机观感要用眼睛看。\n *\n * 运行：node scripts/check-button-radius-coverage.js\n * 退出码：不变量全过且反例全被拦下时为 0，否则 1。\n */\n\nconst fs = require('fs')\nconst path = require('path')\n\nconst ROOT = path.resolve(__dirname, '..')\nconst SRC = path.join(ROOT, 'src')\n\n// 注意：本仓脚本跑在浏览器迷你运行器里，readdirSync 不支持 withFileTypes，\n// 一律 readdirSync + statSync 判断目录；同步代码，只用 fs/path。\nconst walk = (dir, out = []) => {\n  for (const name of fs.readdirSync(dir)) {\n    const full = path.join(dir, name)\n    if (fs.statSync(full).isDirectory()) walk(full, out)\n    else if (/\\.(ts|tsx|js|jsx)$/.test(name)) out.push(full)\n  }\n  return out\n}\n\n// 去注释（块注释替换为等量空白，保留行号；行注释去掉但保留换行）。\n// CRLF 归一到 LF，方便反例做整行替换。\nconst stripComments = (t) =>\n  t\n    .replace(/\\/\\*[\\s\\S]*?\\*\\//g, (m) => m.replace(/[^\\n]/g, ' '))\n    .replace(/(^|[^:])\\/\\/[^\\n]*/gm, '$1')\n\nconst rel = (f) => path.relative(ROOT, f).split(path.sep).join('/')\nconst FILES = walk(SRC).map((f) => ({\n  path: rel(f),\n  text: fs.readFileSync(f, 'utf8').replace(/\\r\\n/g, '\\n'),\n}))\n\n// ---------------------------------------------------------------------------\n// 判定模式\n// ---------------------------------------------------------------------------\n// 按钮底色令牌：c-button-background 前缀已含 -active / -selected / -hover 各变体\nconst BUTTON_TOKEN = /c-button-background/\n// 「行内覆盖」只认 borderRadius: buttonRadius(...) 这一种写法（静态 borderRadius 是兜底，不算接线）\nconst INLINE_OVERRIDE = /borderRadius:\\s*buttonRadius\\(/\nconst IMPORT_HOOK = /import\\s*\\{[^}]*\\buseButtonRadius\\b[^}]*\\}\\s*from\\s*'@\\/utils\\/buttonRadius'/\nconst HOOK_CALL = /const\\s+buttonRadius\\s*=\\s*useButtonRadius\\(\\s*\\)/\n\n// 具名豁免：这些 .tsx 里的按钮令牌**经逐行复核确认不属本文件可控的按钮外观**，\n// 因而本文件无需接线。豁免必须「具名到文件 + 写明理由」，绝不放开令牌判定本身：\n// 不在名单里的文件漏接一律照拦（见 D 段反例），名单条目腐化（文件已不再出现令牌）\n// 亦判失败，逼着同步删除过期条目 —— 否则豁免会长期掩盖一个已改名/已删令牌的文件。\nconst TOKEN_EXEMPT = {\n  'src/components/MetadataEditModal/ParseName.tsx':\n    '令牌只出现在传给 ButtonPrimary 的 style 底色里，而 ButtonPrimary 只解构 disabled/size/onPress/children、该 style 整个被丢弃（底色与圆角都由 ButtonPrimary 自身按同一令牌 + buttonRadius(28) 重算）——本文件没有任何可控的按钮外观',\n  'src/screens/Home/Views/Setting/components/Slider.tsx':\n    '令牌只作滑条轨道/底槽 tint；轨道不是按钮族，其圆角属容器令牌（designRadius）管辖',\n}\n\n// A. 使用按钮令牌的 .tsx 文件 → 必须接线（import + 调用 + 行内覆盖）\nconst checkTokenFiles = (files) => {\n  const rows = []\n  const hits = []\n  const seenExempt = new Set()\n  for (const f of files) {\n    if (!/\\.tsx$/.test(f.path)) continue\n    const code = stripComments(f.text)\n    if (!BUTTON_TOKEN.test(code)) continue\n    if (TOKEN_EXEMPT[f.path]) {\n      seenExempt.add(f.path)\n      rows.push({ path: f.path, ok: true, exempt: true, miss: `〔具名豁免〕${TOKEN_EXEMPT[f.path]}` })\n      continue\n    }\n    const miss = []\n    if (!IMPORT_HOOK.test(code)) miss.push(\"缺 import { useButtonRadius } from '@/utils/buttonRadius'\")\n    if (!HOOK_CALL.test(code)) miss.push('缺 const buttonRadius = useButtonRadius() 调用')\n    if (!INLINE_OVERRIDE.test(code)) miss.push('缺 borderRadius: buttonRadius(...) 行内覆盖')\n    const ok = miss.length === 0\n    rows.push({ path: f.path, ok, miss: ok ? '' : miss.join('；') })\n    if (!ok) hits.push(`${f.path}  —  ${miss.join('；')}`)\n  }\n  // 豁免腐化反查：列入名单却已扫不到令牌 → 失败（该条目已过期，必须同步删除）\n  for (const p of Object.keys(TOKEN_EXEMPT)) {\n    if (!seenExempt.has(p)) {\n      hits.push(`具名豁免已过期：${p} 已不再使用按钮令牌，请从 TOKEN_EXEMPT 删除该条目`)\n    }\n  }\n  return { rows, hits, total: rows.length }\n}\n\n// B. useButtonRadius() 调用面的 import 来源 / 调用形态 / 组件内位置\nconst checkHookUsage = (files) => {\n  const hits = []\n  for (const f of files) {\n    // hook 定义文件自身不参与（它的函数声明也含 useButtonRadius(）\n    if (/utils\\/buttonRadius\\.(ts|tsx|js)$/.test(f.path)) continue\n    const code = stripComments(f.text)\n    const occurrences = (code.match(/\\buseButtonRadius\\s*\\(/g) || []).length\n    const hasImport = IMPORT_HOOK.test(code)\n    if (!occurrences && !hasImport) continue\n    if (occurrences && !hasImport) {\n      hits.push(`${f.path} 调用了 useButtonRadius() 但没有 import { useButtonRadius } from '@/utils/buttonRadius'（或来源不对）`)\n      continue\n    }\n    if (hasImport && !occurrences) {\n      hits.push(`${f.path} import 了 useButtonRadius 但一次都没调用（死 import？）`)\n      continue\n    }\n    const declLines = code.split('\\n').filter((l) => HOOK_CALL.test(l))\n    const indented = declLines.filter((l) => /^[ \\t]+/.test(l)).length\n    if (declLines.length !== occurrences) {\n      hits.push(`${f.path} 有调用不是 \\`const buttonRadius = useButtonRadius()\\` 形态（useButtonRadius() 出现 ${occurrences} 处，合规声明仅 ${declLines.length} 处）`)\n    } else if (indented !== declLines.length) {\n      hits.push(`${f.path} 的 useButtonRadius() 声明行没有缩进，疑似在组件外（hook 必须写在组件/自定义 hook 函数体内）`)\n    }\n  }\n  return hits\n}\n\n// C. 用户点名的八类面 → 真实文件清单 + 中文说明（路径全部在本仓实存，接线已在位）\nconst REQUIRED = [\n  ['src/components/home/PlaylistCard.tsx', '歌单封面：推荐页歌单卡片的封面（按卡片自身宽度折算半高 buttonRadius(width)）'],\n  ['src/screens/SonglistDetail/Header.tsx', '歌单封面：歌单详情页顶部大封面（设计边长 70）'],\n  ['src/screens/SonglistDetail/index.tsx', '歌单封面：歌单详情页收拢/小尺寸封面（设计边长 104）'],\n  ['src/screens/Home/Views/Discovery/index.tsx', '排行榜按钮：推荐页「排行榜」区块的榜单卡片（卡高 ≈64）与同页历史按钮（42）'],\n  ['src/components/home/PlatformChips.tsx', '酷我音乐按钮：推荐页平台胶囊（酷我/酷狗/企鹅等，高 ≈34）'],\n  ['src/screens/Home/Views/Search/HeaderBar/index.tsx', '搜索页的搜索框：48pt 外层容器（同文件还有搜索平台胶囊 38）'],\n  ['src/screens/Home/Views/Search/HeaderBar/SearchInput.tsx', '搜索页的搜索框：内部 40pt 输入框'],\n  ['src/screens/Home/Views/Search/SearchTypeSelector.tsx', '搜索框下面的按钮：歌曲/歌单/歌手/专辑类型切换（高 36）'],\n  ['src/screens/Home/Views/Search/BlankView/HotSearch.tsx', '热门搜索下面的容器：热门词条胶囊（高 44）'],\n  ['src/screens/Home/Views/Search/BlankView/HistorySearch.tsx', '历史搜索下面的容器：历史词条胶囊（36）/ 行内删除钮（18）/ 清空历史钮（32）'],\n  ['src/screens/Home/Views/Setting/components/Button.tsx', '设置中所有的按钮：动作按钮（设计高 40）'],\n  ['src/screens/Home/Views/Setting/Vertical/Main.tsx', '设置中所有的按钮：竖屏分类入口行（设计高 56）'],\n  ['src/screens/Home/Views/Setting/Vertical/NavList.tsx', '设置中所有的按钮：竖屏分类 Tab（高 40）'],\n  ['src/screens/Home/Views/Setting/Horizontal/NavList.tsx', '设置中所有的按钮：横屏分类导航（高 44）'],\n  ['src/screens/Home/Views/Setting/components/InputItem.tsx', '设置中所有的按钮：设置项输入框（高 36）'],\n]\n\n// C 的传参钉子：钩子还在但行内覆盖被删/改数值时立刻失败\nconst PINNED = [\n  ['src/components/home/PlaylistCard.tsx', /buttonRadius\\(\\s*width\\s*\\)/, '歌单封面按自身宽度 buttonRadius(width)'],\n  ['src/screens/SonglistDetail/Header.tsx', /buttonRadius\\(\\s*70\\s*\\)/, '歌单详情顶封 buttonRadius(70)'],\n  ['src/screens/SonglistDetail/index.tsx', /buttonRadius\\(\\s*104\\s*\\)/, '歌单详情收拢封面 buttonRadius(104)'],\n  // 榜单卡传参随宽窄两态取不同设计高度（窄 64 / 宽 72）。钉子必须把两态一起咬住：\n  // 退化成单值（无论 64 还是 72）都说明某一态的高度口径又丢了，正则故意不接受裸 64。\n  ['src/screens/Home/Views/Discovery/index.tsx', /buttonRadius\\(\\s*wide\\s*\\?\\s*72\\s*:\\s*64\\s*\\)/, '榜单卡片 buttonRadius(wide ? 72 : 64)'],\n  ['src/components/home/PlatformChips.tsx', /buttonRadius\\(\\s*34\\s*\\)/, '平台胶囊 buttonRadius(34)'],\n  ['src/screens/Home/Views/Search/HeaderBar/index.tsx', /buttonRadius\\(\\s*48\\s*\\)/, '搜索框容器 buttonRadius(48)'],\n  ['src/screens/Home/Views/Search/HeaderBar/index.tsx', /buttonRadius\\(\\s*38\\s*\\)/, '搜索平台胶囊 buttonRadius(38)'],\n  ['src/screens/Home/Views/Search/HeaderBar/SearchInput.tsx', /buttonRadius\\(\\s*40\\s*\\)/, '搜索输入框 buttonRadius(40)'],\n  ['src/screens/Home/Views/Search/SearchTypeSelector.tsx', /buttonRadius\\(\\s*36\\s*\\)/, '类型切换按钮 buttonRadius(36)'],\n  ['src/screens/Home/Views/Search/BlankView/HotSearch.tsx', /buttonRadius\\(\\s*44\\s*\\)/, '热门词条按钮 buttonRadius(44)'],\n  ['src/screens/Home/Views/Search/BlankView/HistorySearch.tsx', /buttonRadius\\(\\s*36\\s*\\)/, '历史词条按钮 buttonRadius(36)'],\n  ['src/screens/Home/Views/Search/BlankView/HistorySearch.tsx', /buttonRadius\\(\\s*18\\s*\\)/, '历史行内删除钮 buttonRadius(18)'],\n  ['src/screens/Home/Views/Search/BlankView/HistorySearch.tsx', /buttonRadius\\(\\s*32\\s*\\)/, '清空历史按钮 buttonRadius(32)'],\n  ['src/screens/Home/Views/Setting/components/Button.tsx', /buttonRadius\\(\\s*40\\s*\\)/, '动作按钮 buttonRadius(40)'],\n  ['src/screens/Home/Views/Setting/Vertical/Main.tsx', /buttonRadius\\(\\s*56\\s*\\)/, '分类入口 buttonRadius(56)'],\n  ['src/screens/Home/Views/Setting/Vertical/NavList.tsx', /buttonRadius\\(\\s*40\\s*\\)/, '分类 Tab buttonRadius(40)'],\n  ['src/screens/Home/Views/Setting/Horizontal/NavList.tsx', /buttonRadius\\(\\s*44\\s*\\)/, '横屏导航按钮 buttonRadius(44)'],\n  ['src/screens/Home/Views/Setting/components/InputItem.tsx', /buttonRadius\\(\\s*36\\s*\\)/, '设置项输入框 buttonRadius(36)'],\n]\n\nconst checkRequired = (files) => {\n  const hits = []\n  const get = (p) => {\n    const hit = files.find((f) => f.path === p)\n    return hit ? hit.text : null\n  }\n  for (const [file, what] of REQUIRED) {\n    const text = get(file)\n    if (!text) {\n      hits.push(`${what}：文件不存在 ${file}`)\n      continue\n    }\n    const code = stripComments(text)\n    if (!IMPORT_HOOK.test(code)) hits.push(`${what}：${file} 缺 import`)\n    if (!HOOK_CALL.test(code)) hits.push(`${what}：${file} 缺 const buttonRadius = useButtonRadius()`)\n    if (!INLINE_OVERRIDE.test(code)) hits.push(`${what}：${file} 缺行内 borderRadius: buttonRadius(...)`)\n  }\n  for (const [file, re, what] of PINNED) {\n    const text = get(file)\n    if (!text || !re.test(stripComments(text))) hits.push(`传参钉子未命中：${what}（${file}）`)\n  }\n  return hits\n}\n\n// ---------------------------------------------------------------------------\n// 断言\n// ---------------------------------------------------------------------------\nconst assertions = []\nlet failed = 0\n\nconst aResult = checkTokenFiles(FILES)\nassertions.push({\n  name: `A 按钮令牌 .tsx 文件必须接线 useButtonRadius（import + 调用 + 行内覆盖）；扫描到 ${aResult.total} 个，逐个断言`,\n  hits: aResult.hits,\n  rows: aResult.rows,\n})\nassertions.push({\n  name: 'B useButtonRadius() 必须 import 自 @/utils/buttonRadius、必须为 `const buttonRadius = useButtonRadius()` 形态且在组件内',\n  hits: checkHookUsage(FILES),\n})\nassertions.push({\n  name: `C 八类点名面 REQUIRED 清单（${REQUIRED.length} 文件）+ 传参钉子（${PINNED.length} 条）`,\n  hits: checkRequired(FILES),\n})\n\n// ---------------------------------------------------------------------------\n// 反例自检：接线被拆掉时必须拦下；替换未命中同样算失败（防反例老化）\n// ---------------------------------------------------------------------------\nconst tamperFiles = (targetPath, patched) =>\n  FILES.map((f) => (f.path === targetPath ? { ...f, text: patched } : f))\n\nconst counterExamples = []\nconst CE = (name, targetPath, mutate, fn, expectSubstr) => {\n  const orig = FILES.find((f) => f.path === targetPath)\n  const patched = orig ? mutate(orig.text) : ''\n  if (!orig || patched === orig.text) {\n    counterExamples.push({ name, ok: false, detail: `替换未命中（${targetPath} 源码已变，反例需同步）` })\n    return\n  }\n  const hits = fn(tamperFiles(targetPath, patched))\n  const match = hits.find((h) => h.includes(expectSubstr))\n  counterExamples.push({\n    name,\n    ok: !!match,\n    detail: match\n      ? '被拦下：' + match\n      : `未被任何不变量拦下（守卫无效；本次 hits=${hits.length}，均不含 ${expectSubstr}）`,\n  })\n}\n\nCE(\n  'D1 删掉 import（搜索类型切换按钮）',\n  'src/screens/Home/Views/Search/SearchTypeSelector.tsx',\n  (t) => t.replace(\"import { useButtonRadius } from '@/utils/buttonRadius'\\n\", ''),\n  checkHookUsage,\n  'src/screens/Home/Views/Search/SearchTypeSelector.tsx',\n)\nCE(\n  'D2 删掉 useButtonRadius() 调用（确认框）',\n  'src/components/common/ConfirmAlert.tsx',\n  (t) => t.replace(/^[ \\t]*const buttonRadius = useButtonRadius\\(\\)[ \\t]*\\n/m, ''),\n  checkHookUsage,\n  'src/components/common/ConfirmAlert.tsx',\n)\nCE(\n  'D3 删掉行内覆盖（歌单封面）',\n  'src/components/home/PlaylistCard.tsx',\n  (t) => t.replace('{ borderRadius: buttonRadius(width) },', '{ borderRadius: 4 },'),\n  checkRequired,\n  'src/components/home/PlaylistCard.tsx',\n)\nCE(\n  'D4 把 useButtonRadius() 挪出组件（热门搜索）',\n  'src/screens/Home/Views/Search/BlankView/HotSearch.tsx',\n  (t) => t.replace(/^[ \\t]+const buttonRadius = useButtonRadius\\(\\)$/m, 'const buttonRadius = useButtonRadius()'),\n  checkHookUsage,\n  'src/screens/Home/Views/Search/BlankView/HotSearch.tsx',\n)\nCE(\n  'D5 import 来源改错（设置动作按钮）',\n  'src/screens/Home/Views/Setting/components/Button.tsx',\n  (t) => t.replace(\"from '@/utils/buttonRadius'\", \"from '@/utils/buttonRadiusX'\"),\n  checkHookUsage,\n  'src/screens/Home/Views/Setting/components/Button.tsx',\n)\nCE(\n  'D6 删掉 REQUIRED 文件的调用（搜索输入框）',\n  'src/screens/Home/Views/Search/HeaderBar/SearchInput.tsx',\n  (t) => t.replace(/^[ \\t]*const buttonRadius = useButtonRadius\\(\\)[ \\t]*\\n/m, ''),\n  checkRequired,\n  'src/screens/Home/Views/Search/HeaderBar/SearchInput.tsx',\n)\nCE(\n  'D7 令牌文件的行内覆盖删掉（通用主按钮）',\n  'src/components/common/ButtonPrimary.tsx',\n  (t) => t.replace('borderRadius: buttonRadius(28)', 'borderRadius: 4'),\n  (files) => checkTokenFiles(files).hits,\n  'src/components/common/ButtonPrimary.tsx',\n)\nCE(\n  'D8 令牌文件删掉全部调用（公告弹窗两个组件）',\n  'src/navigation/components/AnnouncementModal.tsx',\n  (t) => t.replace(/^[ \\t]*const buttonRadius = useButtonRadius\\(\\)[ \\t]*\\n/gm, ''),\n  (files) => checkTokenFiles(files).hits,\n  'src/navigation/components/AnnouncementModal.tsx',\n)\nCE(\n  'D9 令牌文件删掉 import（添加歌曲弹窗）',\n  'src/components/MusicAddModal/MusicAddModal.tsx',\n  (t) => t.replace(\"import { useButtonRadius } from '@/utils/buttonRadius'\\n\", ''),\n  (files) => checkTokenFiles(files).hits,\n  'src/components/MusicAddModal/MusicAddModal.tsx',\n)\nCE(\n  'D10 调用改名（同步模式弹窗）',\n  'src/navigation/components/SyncModeModal.tsx',\n  (t) => t.replace(/const buttonRadius = useButtonRadius\\(\\)/g, 'const br = useButtonRadius()'),\n  checkHookUsage,\n  'src/navigation/components/SyncModeModal.tsx',\n)\n// 宽屏榜单卡两态高度退化成单值：钉子必须咬住「宽窄高度口径丢失」，\n// 否则改回裸 64 会让宽屏变体的 72 分母无声消失。\nCE(\n  'D11 榜单卡传参退化成单值（宽屏变体高度口径丢失）',\n  'src/screens/Home/Views/Discovery/index.tsx',\n  (t) => t.replace('buttonRadius(wide ? 72 : 64)', 'buttonRadius(64)'),\n  checkRequired,\n  '榜单卡片',\n)\n\n// ---------------------------------------------------------------------------\n// 输出\n// ---------------------------------------------------------------------------\nconsole.log('='.repeat(92))\nconsole.log('按钮圆角（theme.buttonRadius）接线覆盖面回归')\nconsole.log('='.repeat(92))\nconsole.log('  A 按钮令牌文件必须接线 useButtonRadius（import + 调用 + 行内覆盖）')\nconsole.log('  B useButtonRadius() 必须来自 @/utils/buttonRadius、形态合规、写在组件内')\nconsole.log('  C 八类点名面（歌单封面/排行榜/酷我/搜索框/搜索框下方/热门/历史/设置按钮）逐文件断言')\nconsole.log('  （本脚本不重复 sim-radius-tokens.js 已钉的令牌值与封面静态值，只钉「接线」）')\nconsole.log()\n\nconsole.log('='.repeat(92))\nconsole.log('断言')\nconsole.log('='.repeat(92))\nfor (const a of assertions) {\n  const ok = a.hits.length === 0\n  if (!ok) failed++\n  console.log(`  ${ok ? '✅' : '❌'}  ${a.name}`)\n  if (a.rows) {\n    for (const r of a.rows) {\n      console.log(`        ${r.ok ? '·' : '✗'} ${r.path}${r.miss ? '  —  ' + r.miss : ''}`)\n    }\n  } else {\n    for (const h of a.hits.slice(0, 40)) console.log(`        ${h}`)\n    if (a.hits.length > 40) console.log(`        ...（共 ${a.hits.length} 处，已截断）`)\n  }\n}\n\nconsole.log()\nconsole.log('='.repeat(92))\nconsole.log('反例自检（接线被拆掉时必须拦下；替换未命中同样算失败）')\nconsole.log('='.repeat(92))\nfor (const c of counterExamples) {\n  if (!c.ok) failed++\n  console.log(`  ${c.ok ? '✅' : '❌'}  ${c.name}　← ${c.detail}`)\n}\n\nconst aOk = assertions.filter((a) => a.hits.length === 0).length\nconst ceOk = counterExamples.filter((c) => c.ok).length\nconsole.log()\nconsole.log(`结果：断言 ${aOk}/${assertions.length} 通过；反例 ${ceOk}/${counterExamples.length} 拦下`)\n\nprocess.exit(failed ? 1 : 0)\n" },
  { n: "sim-jsx-import-guard.js", s: "#!/usr/bin/env node\n/**\n * sim-jsx-import-guard.js —— 「JSX 里用到的组件必须有绑定（导入/声明）」契约不变量\n * （第 20 轮·图一，2026-10-03）。\n *\n * 需求来源（用户原话）：\n *   「当我输入网易云音乐 cookie 后，点击网易云每日推荐后报错，如图，软件再也进不去了」。\n *\n * 根因：src/screens/Home/Views/DailyRec/index.tsx 的 Tabs 里用了 <ScrollView>（横向滑动\n * 的两个主 tab），但 react-native 的具名导入里从来没有它 —— 渲染到 Tabs 就抛\n * ReferenceError: Property 'ScrollView' doesn't exist，整棵组件树直接崩（不是渲染报错兜底，\n * 是进页面即炸）。本工程没有编译/运行环境，验证只有「真解析器扫语法 + 契约脚本」两道；\n * 解析器只管语法对不对（少一个导入语法完全合法），此前的结构脚本也只查 JSX 形状 ——\n * 本脚本把「JSX 标识符的绑定缺口」这一类纳入契约。\n *\n * 覆盖面：src 下所有 .ts/.tsx。对白名单 RN_JSX_NAMES 里的名字，只要在（剥注释、挖字符串后的）\n * 源码里出现 JSX 形态的使用（`<Name` 后跟空白 / `>` / `/` / `.`，含 <Animated.View> 这种\n * 成员表达式），就必须在同一个文件里有绑定，三者其一：\n *   a) 出现在任一 `import … from '…'` 语句里（不限来源：react-native / 本仓组件 / 第三方库都算）；\n *   b) 本地声明（const / let / var / function / class Name）；\n *   c) 解构取值（`{ … Name … } = …` 形态，如 const { Name } = props）。\n * 注释先剥离、字符串先挖空 —— 注释里写 <ScrollView> 不算使用、也不当绑定。\n *\n * 白名单刻意收窄到「react-native 常见 JSX 组件名 + Animated」：\n * 泛型参数（<T,> / <T extends object>）不在名单里，从构造上不会误报；\n * 「扫描器报红但其实是合法代码」会让契约本身失去可信度，宁可窄一点、每条都是真亏。\n * 已知边界（如实声明）：不在白名单里的冷门 RN 导出（如 DrawerLayoutAndroid 之外的新组件）\n * 漏导入时本脚本抓不到 —— 白名单就是本脚本的全部射程。\n *\n * 反例自检（变异真实源码 + 合成片段；替换未命中 = 脚本自身失败）：\n *   m1 把 DailyRec 的 ScrollView 从 react-native 具名导入里删掉 → 必须报（图一本体）\n *   m2 把该导入改成注释 → 必须报（注释不是绑定）\n * 防误报正例（合成片段，必须不报）：\n *   p1 使用只出现在注释里   p2 泛型 <T,> / <P extends object>\n *   p3 字符串里的 '<ScrollView>'   p4 本地声明 const ScrollView = …（无导入）\n *   p5 同片段里 <View> 有导入、<Image> 没有 → 只报 Image，不连坐 View\n *\n * 运行：node scripts/sim-jsx-import-guard.js\n * 退出码：不变量全过、且全部反例被拦下时为 0，否则 1。\n */\n\nconst fs = require('fs')\nconst path = require('path')\n\nconst ROOT = path.resolve(__dirname, '..')\nconst SRC = path.join(ROOT, 'src')\n\nconst DAILY_REC = 'src/screens/Home/Views/DailyRec/index.tsx'\nconst REAL_DAILY_REC = fs.readFileSync(path.join(ROOT, DAILY_REC), 'utf8')\n\n/** JSX 里会用到的 react-native 组件名白名单（+ Animated，对应 <Animated.View> 形态）。 */\nconst RN_JSX_NAMES = [\n  'View',\n  'Text',\n  'Image',\n  'ImageBackground',\n  'ScrollView',\n  'FlatList',\n  'SectionList',\n  'VirtualizedList',\n  'SafeAreaView',\n  'Modal',\n  'Switch',\n  'Button',\n  'TextInput',\n  'KeyboardAvoidingView',\n  'ActivityIndicator',\n  'RefreshControl',\n  'StatusBar',\n  'Pressable',\n  'TouchableOpacity',\n  'TouchableHighlight',\n  'TouchableWithoutFeedback',\n  'TouchableNativeFeedback',\n  'Animated',\n]\n\nconst stripComments = (src) =>\n  src.replace(/\\/\\*[\\s\\S]*?\\*\\//g, '').replace(/\\/\\/[^\\n]*/g, '')\n\n/** 字符串字面量挖空（含模板串）：注释/文案里提到的 <ScrollView> 不参与判定。 */\nconst blankStrings = (src) =>\n  src\n    .replace(/'(?:\\\\.|[^'\\\\\\n])*'/g, \"''\")\n    .replace(/\"(?:\\\\.|[^\"\\\\\\n])*\"/g, '\"\"')\n    .replace(/`(?:\\\\.|[^`\\\\])*`/g, '``')\n\n/** 目录遍历：本仓脚本跑在浏览器迷你运行器里，readdirSync 不支持 withFileTypes，\n *  一律 readdirSync + statSync 判断目录（见 check-button-opacity-coverage.js 的同一备注）。 */\nconst walk = (dir, out = []) => {\n  for (const name of fs.readdirSync(dir)) {\n    const full = path.join(dir, name)\n    if (fs.statSync(full).isDirectory()) {\n      if (name !== 'node_modules') walk(full, out)\n    } else if (/\\.(ts|tsx)$/.test(name)) out.push(full)\n  }\n  return out\n}\n\nconst escapeRe = (s) => s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&')\n\n/** 该名字在（已剥注释、但保留字符串内容的）源码里有没有绑定：导入 / 本地声明 / 解构。\n *  注意：判定绑定必须保留字符串 —— import 的模块路径本身就是字符串（'react-native'），\n *  先挖字符串会让 `from '…'` 变成 `from ''`，所有导入都匹配不上（本脚本初版就栽在这）。 */\nconst isBound = (code, name) => {\n  const n = escapeRe(name)\n  // a) 任一 import … from '…' 语句里出现该名字（含 type 导入 —— 宽松侧，宁可放过）\n  const importSegs = code.match(/import[\\s\\S]*?from\\s*['\"][^'\"]+['\"]/g) ?? []\n  if (importSegs.some((seg) => new RegExp('\\\\b' + n + '\\\\b').test(seg))) return true\n  // b) 本地声明\n  if (new RegExp('\\\\b(?:const|let|var|function|class)\\\\s+' + n + '\\\\b').test(code)) return true\n  // c) 解构取值（const { A, Name } = … / ({ Name } = props)）\n  if (new RegExp('\\\\{[^}]*\\\\b' + n + '\\\\b[^}]*\\\\}\\\\s*=').test(code)) return true\n  return false\n}\n\n/** 分析一份源码：JSX 形态用到的白名单名字 / 其中没有绑定的。\n *  两个视图：used 看「剥注释 + 挖字符串」的（字符串里写标签不算使用）；\n *  bound 看「剥注释、留字符串」的（导入路径是字符串，不能被挖掉）。 */\nconst analyze = (src) => {\n  const commented = stripComments(src)\n  const code = blankStrings(commented)\n  const used = new Set()\n  const re = /<([A-Z][A-Za-z0-9_]*)(?=[\\s/>.])/g\n  let m\n  while ((m = re.exec(code))) {\n    if (RN_JSX_NAMES.includes(m[1])) used.add(m[1])\n  }\n  const unbound = [...used].filter((n) => !isBound(commented, n)).sort()\n  return { used: [...used], unbound }\n}\n\n/** 全仓扫描：文件数 / JSX 使用次数（扫描确实在工作）/ 违规清单。 */\nconst scanProject = () => {\n  const files = walk(SRC)\n  const violations = []\n  let usages = 0\n  for (const full of files) {\n    const { used, unbound } = analyze(fs.readFileSync(full, 'utf8'))\n    usages += used.length\n    if (unbound.length) {\n      violations.push({ file: path.relative(ROOT, full).replace(/\\\\/g, '/'), names: unbound })\n    }\n  }\n  return { files: files.length, usages, violations }\n}\n\n// ---------------------------------------------------------------------------\n// 不变量（真实源码）\n// ---------------------------------------------------------------------------\n\nconst SCAN = scanProject()\n\nconst invariants = () => {\n  const reasons = []\n\n  // ① 全仓零违规：src 下没有任何「JSX 用了、文件里却没绑定」的白名单名字\n  if (SCAN.violations.length) {\n    for (const v of SCAN.violations) {\n      reasons.push(`${v.file} 里 ${v.names.join(' / ')} 以 JSX 形态使用但文件内无绑定（缺导入/声明）`)\n    }\n  }\n\n  // ② 扫描器确实在工作（防止 walk 坏了返回空表 → 0 违规假绿）\n  //    地板取当前实况（706 文件 / 796 处「文件×名字」去重使用）往下留余量：删掉整页也不会踩到，\n  //    但 walk 或 usage 正则一坏（掉到 0 附近）立刻翻红。\n  if (SCAN.files < 650) reasons.push(`扫描面异常：只扫到 ${SCAN.files} 个文件（应 ≥650）`)\n  if (SCAN.usages < 700) reasons.push(`扫描面异常：白名单 JSX 使用只统计到 ${SCAN.usages} 处（应 ≥700）`)\n\n  // ③ 图一的具体回归钉：DailyRec 的 ScrollView 导入与使用都在\n  const dailyCode = blankStrings(stripComments(REAL_DAILY_REC))\n  const rnImport = REAL_DAILY_REC.match(/import\\s*\\{[^}]*\\}\\s*from\\s*'react-native'/)\n  if (!rnImport || !/\\bScrollView\\b/.test(rnImport[0])) {\n    reasons.push('DailyRec 的 react-native 具名导入里没有 ScrollView（图一会复发）')\n  }\n  if (!/<ScrollView[\\s/>.]/.test(dailyCode)) {\n    reasons.push('DailyRec 里已不再以 JSX 形态使用 <ScrollView（锚点漂移，请先核对脚本）')\n  }\n\n  return reasons\n}\n\n// ---------------------------------------------------------------------------\n// 反例（变异真实源码 / 合成片段）\n// ---------------------------------------------------------------------------\n\nconst results = []\nconst check = (name, fn, expected) => {\n  let reasons\n  try {\n    reasons = fn()\n  } catch (e) {\n    reasons = ['脚本自身异常: ' + (e && e.message ? e.message : String(e))]\n  }\n  const ok = reasons.length > 0\n  results.push({ name, ok, detail: reasons, expected })\n  return ok\n}\n\nconst tamper = (src, oldStr, newStr) => {\n  if (!src.includes(oldStr)) {\n    throw new Error('替换未命中（脚本锚点漂移）: ' + oldStr.slice(0, 60))\n  }\n  return src.replace(oldStr, newStr)\n}\n\nconst runCounterExamples = () => {\n  // m1 删掉 DailyRec 的 ScrollView 导入（图一本体）→ 必须报 ScrollView 未绑定\n  check('m1 DailyRec 删掉 ScrollView 导入', () => {\n    const s = tamper(REAL_DAILY_REC,\n      'StyleSheet, ScrollView } from \\'react-native\\'',\n      'StyleSheet } from \\'react-native\\'')\n    const { unbound } = analyze(s)\n    return unbound.includes('ScrollView') ? ['已拦下'] : []\n  }, 'ScrollView 以 JSX 形态使用但无绑定')\n\n  // m2 把 ScrollView 只留在注释里（名字还在、绑定没了）→ 必须报\n  check('m2 ScrollView 只出现在注释里', () => {\n    const s = tamper(REAL_DAILY_REC,\n      'StyleSheet, ScrollView } from \\'react-native\\'',\n      'StyleSheet } from \\'react-native\\' // 曾用过 ScrollView')\n    const { unbound } = analyze(s)\n    return unbound.includes('ScrollView') ? ['已拦下'] : []\n  }, '注释不是绑定')\n\n  // m3 合成片段：<Image /> 无导入且不在注释里 → 必须报（且不连坐已导入的 View）\n  check('m3 合成片段 Image 漏导入', () => {\n    const s = [\n      \"import { View } from 'react-native'\",\n      'export const A = () => <View><Image /></View>',\n    ].join('\\n')\n    const { unbound } = analyze(s)\n    return unbound.length === 1 && unbound[0] === 'Image' ? ['已拦下'] : []\n  }, '只报 Image')\n\n  return results\n}\n\n// ---------------------------------------------------------------------------\n// 防误报正例（合成片段，必须不报）\n// ---------------------------------------------------------------------------\n\nconst runFalsePositiveGuards = () => {\n  const out = []\n  const expectClean = (name, src) => {\n    const { unbound } = analyze(src)\n    out.push({ name, ok: unbound.length === 0, detail: unbound })\n  }\n\n  expectClean('p1 使用只在注释里', 'const x = 1\\n// <ScrollView horizontal />\\n')\n  expectClean('p2 泛型不误报', 'const id = <T,>(x: T) => x\\nconst f = <P extends object>(p: P) => p\\n')\n  expectClean('p3 字符串里的标签', \"const s = '<ScrollView />'\\nconst t = `<ScrollView>`\\n\")\n  expectClean('p4 本地声明算绑定', 'const ScrollView = (props: any) => props.children\\nexport const A = () => <ScrollView />\\n')\n  expectClean('p5 解构取值算绑定', \"const { Animated } = require('react-native')\\nexport const A = () => <Animated.View />\\n\")\n\n  return out\n}\n\n// ---------------------------------------------------------------------------\n// 主流程\n// ---------------------------------------------------------------------------\n\nconsole.log('=== sim-jsx-import-guard ===')\nconsole.log(`扫描 src：${SCAN.files} 个文件，白名单 JSX 使用 ${SCAN.usages} 处`)\n\nconst invReasons = invariants()\nconsole.log('\\n[不变量：JSX 绑定缺口]')\nif (invReasons.length === 0) {\n  console.log('  PASS 全仓 0 违规 + 扫描面正常（文件数/使用数达标）+ DailyRec 的 ScrollView 导入与使用都在')\n} else {\n  invReasons.forEach((r) => console.log('  FAIL ' + r))\n}\n\nconsole.log('\\n[防误报正例（必须不报）]')\nconst fpResults = runFalsePositiveGuards()\nlet fpAllOk = true\nfor (const r of fpResults) {\n  console.log(`  ${r.ok ? 'PASS' : 'FAIL'} ${r.name}${r.ok ? ' —— 未误报' : ` —— 误报：${JSON.stringify(r.detail)}`}`)\n  if (!r.ok) fpAllOk = false\n}\n\nconsole.log('\\n[反例自检（必须拦下）]')\nconst ceResults = runCounterExamples()\nlet ceAllOk = true\nfor (const r of ceResults) {\n  console.log(`  ${r.ok ? 'PASS' : 'FAIL'} ${r.name} —— ${r.ok ? '已拦下' : `未拦下（reasons=${JSON.stringify(r.detail)}）`}`)\n  if (!r.ok) ceAllOk = false\n}\n\nconst invOk = invReasons.length === 0\nconst allOk = invOk && fpAllOk && ceAllOk\nconsole.log(`\\n结果：${allOk ? 'ALL PASS' : '有失败项'}（不变量 ${invOk ? '1/1' : '0/1'}；防误报 ${fpResults.filter(r => r.ok).length}/${fpResults.length}；反例 ${ceResults.filter(r => r.ok).length}/${ceResults.length}）`)\nprocess.exit(allOk ? 0 : 1)\n" },
]

const fmt = (v) => {
  if (typeof v === 'string') return v
  try { return JSON.stringify(v) } catch (e) { return String(v) }
}

// 与 run.py 的 runner.html 逐字同形的 require 映射（成员平时就是这么跑的）
const makeRequire = () => (name) => {
  if (name === 'fs' || name === 'node:fs') return require('fs')
  if (name === 'path' || name === 'node:path') return require('path')
  if (name === 'os' || name === 'node:os') return { EOL: '\n', platform: () => 'win32', cpus: () => [] }
  if (name === 'child_process' || name === 'node:child_process') return {
    execSync: () => '',
    spawnSync: () => ({ status: 0, stdout: '', stderr: '', error: null }),
    exec: () => ({ on: () => {}, stdout: { on: () => {} }, stderr: { on: () => {} } }),
  }
  if (name === 'util' || name === 'node:util') return { inspect: fmt }
  throw new Error('MODULE_NOT_SUPPORTED: ' + name)
}

// 成员看到的 __dirname / __filename：**拿套件自己的那一份**，两种运行环境下都正确 ——
// 浏览器 runner 里套件作用域的 __dirname 是 '/scripts'（HTTP 根即工程根），
// 真实 node 里是 '<工程根>\scripts'。这里**不能写死** '/scripts'：真实 node 下
// path.resolve('/scripts', '..') 会落到盘根（E:\），成员一律 ENOENT。
const DIRNAME = (typeof __dirname === 'string' && __dirname) ? __dirname : '/scripts'

const RESULTS = []
MEMBERS.forEach((m, i) => {
  const tag = `[${i + 1}/${MEMBERS.length}] ${m.n}`
  console.log(`===== ${tag} =====`)
  const lines = []
  const memberConsole = {
    log: (...a) => lines.push(a.map(fmt).join(' ')),
    error: (...a) => lines.push('[err] ' + a.map(fmt).join(' ')),
    warn: (...a) => lines.push('[warn] ' + a.map(fmt).join(' ')),
  }
  let code = null
  const memberProcess = {
    // runner.html 的 shim 也是「记下退出码，不真的退出」—— 逐字保持同形，
    // 这样「合并前跑一次、合并后跑一次」的输出与退出码才可比
    exit: (c) => { if (code === null) code = (c === undefined ? 0 : c) },
    argv: ['node', 'scripts/' + m.n],
    cwd: () => '/',
    env: {},
    platform: 'win32',
    version: 'v20.11.0',
    versions: { node: '20.11.0' },
  }
  let fatal = null
  try {
    const mod = { exports: {} }
    // 与 runner.html 完全同形的两步预处理：剥掉开头的 BOM 与 shebang
    //（`#!` 不是合法 JS —— 独立跑时由 runner 剥，收进套件后必须由套件自己剥，
    //  否则带 shebang 的成员会当场 SyntaxError），再追加 sourceURL 注释让栈指回成员名
    const src = String(m.s).replace(/^\uFEFF/, '').replace(/^#![^\n]*\r?\n/, '')
    const fn = new Function('require', 'process', 'console', '__dirname', '__filename', 'module', 'exports',
      src + '\n//# sourceURL=scripts/' + m.n)
    fn(makeRequire(), memberProcess, memberConsole, DIRNAME, DIRNAME + '/' + m.n, mod, mod.exports)
  } catch (e) {
    fatal = (e && e.stack) ? e.stack : String(e)
  }
  if (fatal != null) {
    lines.push('[FATAL] ' + fatal)
    if (code === null) code = 1
  }
  for (const l of lines) console.log(l)
  const rc = code === null ? 0 : code
  RESULTS.push({ name: m.n, rc, exited: code !== null })
  console.log(`===== ${tag} → exit ${rc} =====`)
})

const failed = RESULTS.filter((r) => r.rc !== 0)
const noExit = RESULTS.filter((r) => !r.exited)
console.log('')
console.log(`成员 ${RESULTS.length} 个；退出 0 的 ${RESULTS.length - failed.length} 个；`
  + `非 0 的 ${failed.length} 个${noExit.length ? `；没调 process.exit 的 ${noExit.length} 个` : ''}`)
if (failed.length) {
  for (const r of failed) console.log(`  FAIL 成员 ${r.name} → exit ${r.rc}`)
}
console.log(`结果：${failed.length ? '有失败成员' : 'ALL PASS'}（成员 ${RESULTS.length - failed.length}/${RESULTS.length}；`
  + `主题 ${THEME}）`)
process.exit(failed.length ? failed[0].rc : 0)
